export const full = {"courses":[{"id":"ai","title":"AI за 14 дней","description":"От первого осмысленного запроса до собственного AI-проекта. Учитесь проверять ответы и применять AI с пользой.","category":"AI","level":"С нуля","duration":"14 дней · 14 уроков","color":"mint","symbol":"AI","outcome":"Собственный AI-проект и план применения навыков на следующие 30 дней.","skills":["Промптинг","Проверка фактов","AI в учёбе"],"legacy":true,"modules":[{"title":"Основа и осознанная практика","lessons":[{"id":"1","title":"Что такое AI на самом деле","minutes":25,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"2","title":"Контекст и ограничения","minutes":20,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"3","title":"Как уточнить слабый ответ","minutes":20,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"4","title":"Как проверять факты и источники","minutes":25,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"5","title":"Как применять AI в учёбе","minutes":25,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""}]},{"title":"Инструменты и рабочие сценарии","lessons":[{"id":"6","title":"Поиск информации и фактчекинг","minutes":35,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"7","title":"Генерация изображений","minutes":30,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"8","title":"AI для учёбы и продуктивности","minutes":30,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"9","title":"Таблицы и данные","minutes":35,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"10","title":"Основы кода с AI","minutes":40,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""}]},{"title":"От идеи к своему проекту","lessons":[{"id":"11","title":"Автоматизация рутины","minutes":30,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"12","title":"Приватность и этика","minutes":25,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"13","title":"Ваш собственный AI-проект","minutes":40,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""},{"id":"14","title":"Финальный проект и следующий шаг","minutes":45,"theory":[],"example":"","task":"","criteria":[],"question":"","options":[],"correct":0,"explanation":""}]}]},{"id":"python","title":"Python за 21 день","category":"Разработка","level":"С нуля","duration":"21 день · 21 урок","color":"blue","symbol":"Py","description":"От первой переменной до своего инструмента с файлами и тестами. Каждый день — небольшая практика, три недели — одна законченная программа.","outcome":"Личный трекер расходов с JSON-сохранением, отчётом по категориям, обработкой ошибок и набором тестов.","skills":["Python","Файлы и данные","Тестирование"],"modules":[{"title":"Неделя 1. Пишем и понимаем код","lessons":[{"id":"1","title":"Переменные и типы","theory":["Программа хранит значения под именами. В Python присваивание выглядит как price = 250. Имя слева обозначает переменную, значение справа — объект. Строка str записывается в кавычках, целое int — без них; float нужен для дробных чисел.","print выводит значение, а не меняет его. Выражение 200 + 50 складывает числа, а '200' + '50' соединяет строки. Выбирайте тип по смыслу данных и используйте понятные имена. Код курса не запускается на платформе: проверьте его в установленном Python 3."],"example":"price = 250\ncount = 3\ntotal = price * count\nprint(f'Итого: {total} ₽')\n# Итого: 750 ₽","task":"Напишите расчёт стоимости трёх учебных материалов. Задайте цены отдельными числовыми переменными, вычислите сумму и выведите её с подписью. Укажите ожидаемый результат.","criteria":["У цен понятные имена и числовой тип","Сумма вычислена выражением, не вписана вручную","Есть вывод с подписью и ожидаемое число"],"question":"Что получится при вычислении '10' + '5'?","options":["15","'105'","Ошибка деления"],"correct":1,"explanation":"Оба операнда — строки, поэтому + соединяет их, а не складывает числа.","minutes":20},{"id":"2","title":"Ввод и безопасное преобразование","theory":["input всегда возвращает строку. int('12') превращает текст в целое, но int('чай') вызывает ValueError. Не стоит считать любой ввод пользователя правильным.","try/except ValueError позволяет объяснить ошибку, а не завершить программу с трассировкой. После преобразования проверьте предметные ограничения: количество не может быть отрицательным. Для денег в серьёзных системах используют Decimal или целое число копеек, а не неточный float."],"example":"try:\n    count = int(input('Сколько тетрадей? '))\n    if count < 0:\n        print('Нужно число от нуля')\n    else:\n        print(count * 80)\nexcept ValueError:\n    print('Введите целое число')","task":"Запросите месячный бюджет целым числом рублей. Обработайте нечисловой ввод и отрицательное значение. Опишите поведение для 3000, -10 и «нет».","criteria":["input преобразован в int","Есть обработка ValueError и отрицательного бюджета","Описаны все три тестовых ввода"],"question":"Какой тип возвращает input()?","options":["int","bool","str"],"correct":2,"explanation":"Даже если пользователь ввёл цифры, input возвращает текст.","minutes":20},{"id":"3","title":"Условия: решение по правилам","theory":["if выбирает ветку по логическому условию. Операторы ==, !=, <, <=, >, >= сравнивают значения. elif проверяется, только если предыдущая ветка не подошла. else выполняется, когда не подошла ни одна.","Порядок проверок важен. Сначала обработайте узкое условие, затем более широкое. Проверьте границы: если правило «до 1000 включительно», число 1000 должно попадать в <= 1000. Отступы в Python — часть синтаксиса."],"example":"spent = 1200\nbudget = 1500\nif spent > budget:\n    print('Перерасход')\nelif spent == budget:\n    print('Бюджет исчерпан')\nelse:\n    print('Осталось:', budget - spent)","task":"Напишите три ветки для оценки результата теста: 80–100 — «отлично», 50–79 — «есть основа», 0–49 — «повторить». Неверные значения вынесите в отдельную проверку. Проверьте 49, 50 и 80.","criteria":["Диапазон 0–100 проверяется отдельно","Границы 50 и 80 не потеряны","Приведены ожидаемые ответы для трёх значений"],"question":"Какой оператор сравнивает два значения на равенство?","options":["=","==","!="],"correct":1,"explanation":"Один знак = присваивает значение, два == сравнивают.","minutes":20},{"id":"4","title":"Списки, словари и циклы","theory":["Список хранит последовательность: expenses = [100, 250]. for перебирает её элементы. Словарь связывает ключ и значение: {'food': 350}. Вложив словари в список, можно хранить каждую покупку с суммой и категорией.","Накопитель total = 0 обновляют внутри цикла. Обращение item['amount'] получает сумму. Не меняйте размер списка, пока перебираете его: создайте новый список или отдельный результат. Пустой список — обязательный тест для расчёта суммы."],"example":"expenses = [{'category': 'еда', 'amount': 120}, {'category': 'проезд', 'amount': 60}]\ntotal = 0\nfor item in expenses:\n    total += item['amount']\nprint(total)  # 180","task":"Создайте список из трёх расходов со словарями category и amount. Циклом вычислите общую сумму и отдельно сумму категории «учёба». Напишите результат для пустого списка.","criteria":["Каждый расход содержит категорию и сумму","Суммы считаются циклом, не вручную","Пустой список даёт 0"],"question":"Что означает expenses[0]?","options":["Первый элемент списка","Последний элемент","Длина списка"],"correct":0,"explanation":"Индексы в Python начинаются с нуля.","minutes":20},{"id":"5","title":"Функции и тесты","theory":["Функция выделяет повторяемое действие. def total(values): объявляет функцию с параметром. return передаёт результат вызывающему коду; print только показывает текст и не заменяет return.","Хорошая функция расчёта не спрашивает ввод и не печатает меню. Так её можно проверить независимо: assert total([2, 3]) == 5. Тесты выбирают для обычного случая, пустых данных и границ. Тест не доказывает отсутствие всех ошибок, но ловит конкретные регрессии."],"example":"def total(values):\n    return sum(values)\n\nassert total([100, 250]) == 350\nassert total([]) == 0","task":"Напишите remaining(budget, expenses), возвращающую остаток бюджета. Передайте список чисел и добавьте три assert: обычные расходы, пустой список и перерасход.","criteria":["Функция принимает параметры и использует return","Расчёт не зависит от input и print","Три теста включают отрицательный остаток"],"question":"Что делает return?","options":["Всегда печатает результат","Возвращает значение из функции","Повторяет цикл"],"correct":1,"explanation":"return завершает функцию и отдаёт значение вызывающему коду.","minutes":20},{"id":"6","title":"Мини-проект: трекер в памяти","theory":["Мини-проект связывает ввод, структуру данных и расчёт. Минимальная версия может хранить операции только до закрытия программы — это нужно явно указать. Не добавляйте сохранение в файл, пока основной расчёт не проверен.","Сначала напишите функцию итогов, затем данные, потом ввод. Финальный результат — рабочий код и короткая инструкция. Сравните сумму программы с ручным расчётом; добавьте тест отрицательного и нечислового ввода. Не собирайте реальные банковские данные."],"example":"def summarize(items):\n    result = {}\n    for item in items:\n        category = item['category']\n        result[category] = result.get(category, 0) + item['amount']\n    return result\n\nprint(summarize([{'category': 'учёба', 'amount': 300}]))","task":"Соберите консольный трекер: ввод суммы и категории, список минимум из трёх операций, общая сумма и итоги по категориям. Отправьте код, инструкцию запуска и результаты тестов. Обозначьте, что данные живут в памяти.","criteria":["Есть ввод с обработкой ошибочной и отрицательной суммы","Итоги по всем операциям и категориям вычисляются функциями","Есть инструкция и минимум три теста с ожидаемыми результатами"],"question":"Как лучше проверить сумму проекта?","options":["Оценить длину кода","Запустить только с одной покупкой","Сравнить с ручным расчётом и проверить пустой набор"],"correct":2,"explanation":"Независимый ожидаемый результат и граничный случай дают осмысленную проверку.","minutes":40},{"id":"7","title":"Разделяем программу на понятные части","minutes":25,"theory":["Трекер из первой недели удобнее развивать, если ввод, расчёт и вывод разделены. Функция расчёта принимает данные и возвращает результат, не вызывая input. Тогда её можно использовать и в меню, и в тесте. Выделяйте части по ответственности, а не по числу строк.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"def total(items):\n    return sum(item['amount'] for item in items)\n\ndef report(items):\n    return f'Всего: {total(items)} ₽'\n\nprint(report([{'amount': 100}, {'amount': 250}])) # 350 ₽","task":"Разделите свой трекер на функции ввода, расчёта и формирования отчёта. Приведите их сигнатуры и пример вызова; объясните, какую часть можно тестировать без клавиатуры.","criteria":["Три ответственности разделены","Расчёт возвращает значение, а не только печатает","Есть пример вызова с ожидаемой суммой"],"question":"Какую функцию проще тестировать?","options":["Которая сама спрашивает ввод и меняет файлы","Которая получает данные и возвращает расчёт","Которая зависит от глобального меню"],"correct":1,"explanation":"Явные параметры и возвращаемый результат позволяют проверять функцию независимо от интерфейса."}]},{"title":"Неделя 2. Строим надёжную основу","lessons":[{"id":"8","title":"Строки и нормализация ввода","minutes":25,"theory":["strip удаляет пробелы по краям, lower приводит текст к нижнему регистру. Это помогает считать «Учёба» и « учёба » одной категорией. Но нормализация должна соответствовать смыслу: пароль нельзя молча обрезать, а отображаемое имя иногда нужно сохранять в исходном виде.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"def normalize_category(value):\n    return value.strip().lower()\n\nassert normalize_category(' Учёба ') == 'учёба'","task":"Напишите функцию нормализации категории. Отвергните пустой результат и добавьте проверки для « ЕДА », «еда» и строки из пробелов.","criteria":["Пробелы и регистр нормализованы","Пустая категория отклонена","Есть три теста с ожидаемыми результатами"],"question":"Что возвращает ' SQL '.strip().lower()?","options":["'SQL '","' sql '","'sql'"],"correct":2,"explanation":"strip убирает крайние пробелы, lower меняет регистр."},{"id":"9","title":"Словари: отчёт по категориям","minutes":25,"theory":["Словарь удобно использовать как накопитель итогов: ключ — категория, значение — сумма. get(key, 0) даёт ноль, если ключ ещё не появился. Обновляя накопитель, не меняйте сами операции: один и тот же набор должен подходить для нескольких отчётов.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"def by_category(items):\n    result = {}\n    for item in items:\n        key = item['category']\n        result[key] = result.get(key, 0) + item['amount']\n    return result","task":"Сгруппируйте четыре операции по двум категориям. Приведите вход, функцию, ожидаемый словарь и проверку, что исходный список не изменился.","criteria":["Суммы вычисляются для каждого ключа","Новая категория не вызывает KeyError","Исходные операции сохранены"],"question":"Зачем нужен result.get(key, 0)?","options":["Чтобы безопасно начать накопление новой категории","Чтобы удалить категорию","Чтобы отсортировать список"],"correct":0,"explanation":"Начальное значение 0 позволяет добавить первую сумму для ещё отсутствующего ключа."},{"id":"10","title":"Проверяем структуру операции","minutes":25,"theory":["Данные могут быть правильного типа, но неверного смысла. Операция должна содержать непустую категорию и неотрицательную целую сумму в копейках. Не смешивайте рубли и копейки в одном списке. bool в Python является подклассом int, поэтому строгая проверка денежного поля может использовать type(value) is int.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"def valid(item):\n    return (isinstance(item, dict)\n        and isinstance(item.get('category'), str)\n        and bool(item['category'].strip())\n        and type(item.get('amount')) is int\n        and item['amount'] >= 0)","task":"Опишите единую схему операции в копейках и функцию проверки. Добавьте примеры с отсутствующей суммой, отрицательной суммой и корректной записью.","criteria":["Единица суммы явно указана","Типы и обязательные поля проверены","Три случая имеют понятный вердикт"],"question":"Что важнее всего при хранении денежных сумм?","options":["Длина имени переменной","Единая единица и проверка допустимых значений","Цвет редактора"],"correct":1,"explanation":"Смешение рублей и копеек даёт ошибку даже при синтаксически правильном коде."},{"id":"11","title":"Исключения без скрытых ошибок","minutes":25,"theory":["Перехватывайте ожидаемую ошибку там, где её можно объяснить. ValueError подходит для неудачного преобразования строки в число, OSError — для проблем с файлом. Пустой except с pass скрывает сбой: пользователь думает, что работа сохранена, хотя это не так.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"try:\n    amount = int(raw)\nexcept ValueError:\n    print('Нужна целая сумма в копейках')\nelse:\n    print('Ввод распознан:', amount)","task":"Перепишите обработчик except: pass для суммы. Выберите конкретное исключение, понятное сообщение и повторный запрос. Объясните, почему успех нельзя показывать при ошибке.","criteria":["Перехвачено конкретное ожидаемое исключение","Пользователь узнаёт причину и способ исправления","Нет ложного сообщения об успехе"],"question":"Почему except: pass опасен?","options":["Скрывает неудачу и затрудняет исправление","Всегда замедляет программу вдвое","Автоматически удаляет файлы"],"correct":0,"explanation":"Без сообщения и обработки сбой превращается в молчаливую потерю результата."},{"id":"12","title":"Модули и точка входа","minutes":25,"theory":["Разнесите расчёт и интерфейс по модулям: calculations.py содержит функции, app.py запускает меню. При импорте модуль выполняет код верхнего уровня, поэтому вызов main защищают условием __name__ == '__main__'. Так импорт в тест не запустит ввод.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"# app.py\nfrom calculations import total\n\ndef main():\n    print(total([]))\n\nif __name__ == '__main__':\n    main()","task":"Предложите структуру из app.py, calculations.py и test_calculations.py. Покажите импорт функции и защищённую точку входа без циклических импортов.","criteria":["У расчёта и интерфейса разные модули","main защищён проверкой __name__","Тест может импортировать расчёт без запуска меню"],"question":"Зачем проверять __name__ == '__main__'?","options":["Чтобы запретить все импорты","Чтобы запускать меню при любом импорте","Чтобы запускать main при прямом старте файла, но не импорте"],"correct":2,"explanation":"Это отделяет запуск программы от использования её функций в других модулях."},{"id":"13","title":"Файлы и безопасные пути","minutes":25,"theory":["with закрывает файл даже при ошибке. Path из pathlib помогает работать с путями. Для учебной программы используйте отдельный каталог, а не произвольный путь из непроверенного ввода. Режим w перезаписывает содержимое — сначала проверьте, что это именно ваш тестовый файл.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"from pathlib import Path\npath = Path('practice-data') / 'note.txt'\npath.parent.mkdir(exist_ok=True)\nwith path.open('w', encoding='utf-8') as file:\n    file.write('Учебный файл')","task":"Напишите чтение учебного текстового файла в UTF-8 с with. Обработайте отсутствие файла и объясните, почему режим w нельзя использовать для чтения.","criteria":["Есть with и явная кодировка","FileNotFoundError обработан понятно","Объяснена опасность перезаписи режима w"],"question":"Какой режим открывает файл для чтения?","options":["w","r","x"],"correct":1,"explanation":"Режим r читает существующий файл, а w создаёт или перезаписывает."},{"id":"14","title":"JSON: данные между запусками","minutes":25,"theory":["JSON сохраняет списки, словари, строки и числа, но не любую Python-структуру. После json.load данные нужно валидировать: корректный JSON ещё не означает правильные операции. При JSONDecodeError не заменяйте файл пустым набором молча — сохраните исходник для разбора.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"import json\nwith open('expenses.json', encoding='utf-8') as file:\n    items = json.load(file)\n# Далее проверьте список и каждую операцию.\n# При ошибке чтения не показывайте «данные успешно загружены».","task":"Опишите загрузку JSON-операций с проверкой схемы из дня 10. Покажите обработку отсутствующего и повреждённого файла без уничтожения исходника.","criteria":["JSON проверяется как список корректных операций","Отсутствие и повреждение различаются","Повреждённый файл не затирается пустыми данными"],"question":"Достаточно ли успешного json.load для проверки расходов?","options":["Да, JSON всегда содержит правильные расходы","Да, если файл маленький","Нет, нужна проверка структуры и значений"],"correct":2,"explanation":"Парсер проверяет формат JSON, а не предметные ограничения приложения."}]},{"title":"Неделя 3. Доводим до рабочего инструмента","lessons":[{"id":"15","title":"CSV-экспорт для таблиц","minutes":25,"theory":["CSV переносит плоские данные в таблицы. Используйте csv.DictWriter вместо склейки строк запятыми: поля сами могут содержать запятую или кавычку. newline='' помогает корректно записывать строки. Если источник не доверенный, текстовые ячейки с =, +, - или @ требуют защиты от интерпретации формул в табличном редакторе.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"import csv\nwith open('report.csv', 'w', newline='', encoding='utf-8') as f:\n    writer = csv.DictWriter(f, fieldnames=['category', 'amount'])\n    writer.writeheader()\n    writer.writerow({'category': 'учёба', 'amount': 30000})","task":"Составьте CSV-экспорт учебных операций с заголовками. Объясните обработку запятой в категории, единицу суммы и риск формул из чужого текста.","criteria":["Используется модуль csv и строка заголовков","Единица amount описана","Учтены кавычки/запятые и недоверенные текстовые ячейки"],"question":"Почему лучше csv, а не ручная склейка запятыми?","options":["Модуль учитывает разделители и кавычки в полях","Он запускает Python быстрее","Он гарантирует прибыль"],"correct":0,"explanation":"Корректное экранирование сохраняет структуру таблицы при сложных значениях."},{"id":"16","title":"Тесты расчёта и загрузки","minutes":25,"theory":["Тесты должны проверять наблюдаемое поведение. Для total нужны обычный, пустой и граничный наборы. Для загрузчика — корректный JSON, неверная структура и повреждённый текст. Используйте отдельные временные тестовые файлы, а не рабочий файл пользователя.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"def test_total():\n    assert total([]) == 0\n    assert total([{'amount': 100}, {'amount': 50}]) == 150\n# Дополните тестами неверных данных загрузчика.","task":"Подготовьте пять тестовых сценариев трекера: вход, ожидаемый результат и проверяемое правило. Не меньше двух сценариев должны проверять ошибки загрузки.","criteria":["Есть обычный и пустой расчёт","Два случая ошибок загрузки","Тесты не меняют пользовательские файлы"],"question":"На каких файлах безопаснее проверять загрузчик?","options":["На единственной рабочей копии","На отдельных временных тестовых файлах","На системных настройках"],"correct":1,"explanation":"Тестовые файлы изолируют проверку от реальных данных."},{"id":"17","title":"Даты и отчёт за период","minutes":25,"theory":["Дата должна иметь явный формат. datetime.date.fromisoformat читает YYYY-MM-DD и отклоняет несуществующие даты. Для отчёта договоритесь, включены ли обе границы периода, и проверьте операции ровно на границе.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"from datetime import date\nstart = date.fromisoformat('2026-11-01')\nend = date.fromisoformat('2026-11-30')\nwhen = date.fromisoformat('2026-11-12')\nprint(start <= when <= end) # True","task":"Добавьте к схеме поле date. Напишите фильтр за включительный период и тесты даты до начала, на границе и после конца.","criteria":["Формат и валидация даты заданы","Обе границы обрабатываются явно","Приведены три граничных теста"],"question":"Зачем тестировать дату на границе?","options":["Чтобы выбрать цвет отчёта","Чтобы избежать импорта","Чтобы проверить включительность условия"],"correct":2,"explanation":"Именно на границах часто проявляются ошибки < вместо <=."},{"id":"18","title":"Понятный запуск через argparse","minutes":25,"theory":["argparse описывает команды и автоматически показывает --help. Пользователь может выбрать входной файл или режим отчёта без изменения кода. Но разбор аргументов не заменяет валидацию данных и доступности файла.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"import argparse\nparser = argparse.ArgumentParser(description='Учебный трекер')\nparser.add_argument('--input', default='expenses.json')\nargs = parser.parse_args()\nprint('Файл:', args.input)","task":"Добавьте аргумент --input и переключатель --summary. Покажите два примера запуска и текст ошибки для отсутствующего файла без ложного успеха.","criteria":["Аргументы названы и имеют понятные значения","Есть два запуска и --help","Ошибка файла обрабатывается отдельно"],"question":"Что даёт argparse?","options":["Разбор аргументов и справку по командам","Автоматическое исправление любого JSON","Хранение секретов"],"correct":0,"explanation":"argparse улучшает интерфейс запуска, но не выполняет предметную проверку данных."},{"id":"19","title":"Рефакторинг без смены результата","minutes":25,"theory":["Рефакторинг меняет внутреннюю организацию при сохранении поведения. Сначала зафиксируйте тесты, затем убирайте дублирование и неясные имена небольшими шагами. Не совмещайте большую перестройку с новой функцией: трудно понять источник ошибки.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"До: сумма расходов считается одинаковым циклом в трёх местах.\nПосле: одна total(items), вызываемая отчётом и меню.\nКонтроль: старые тестовые входы дают прежние ответы.","task":"Найдите повторение в своём трекере. Покажите до/после, выделенную функцию и тест, подтверждающий неизменный результат.","criteria":["Правка уменьшает реальное дублирование","Поведение и формат результата сохранены","Приведён контрольный тест до/после"],"question":"Как проверить безопасный рефакторинг?","options":["По числу новых файлов","По прохождению тестов прежнего поведения","По длине комментариев"],"correct":1,"explanation":"Тесты помогают увидеть, что перестройка не изменила результат."},{"id":"20","title":"Собираем сценарий целиком","minutes":25,"theory":["Интеграционная проверка проходит путь от входа до сохранённого результата. Для трекера: создать учебную операцию, сохранить, закрыть программу, загрузить заново и сверить сумму. Отдельно проверьте сбой записи: нельзя говорить «сохранено», если запись не удалась.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"Сценарий: 12000 + 8000 копеек → сохранить JSON → новый запуск → сумма 20000 копеек.\nНегативный сценарий: нет прав записи → понятная ошибка, исходные данные сохранены, успех не показан.","task":"Опишите и, если среда доступна, выполните полный сценарий сохранения и повторной загрузки. Укажите вход, ожидаемые значения, фактическое наблюдение либо честный план проверки.","criteria":["Есть перезапуск и сверка загруженных данных","Сбой записи проверяется отдельно","План не выдан за фактически выполненный тест"],"question":"Когда можно сообщать «сохранено»?","options":["До записи, чтобы не ждать","После создания переменной","Только после успешной записи"],"correct":2,"explanation":"Сообщение об успехе должно соответствовать реальному сохранению."},{"id":"21","title":"Итог: личный Python-инструмент","minutes":45,"theory":["Финальный проект объединяет три недели: безопасные данные, функции, файлы, отчёты и тестирование. Минимальный результат — трекер, который не теряет операции между запусками, объясняет ошибки и формирует отчёт. Не нужен платный сервис или чужие финансовые сведения.","Разбирайте пример построчно и сначала сформулируйте ожидаемый результат. Код здесь не выполняется: проверяйте его в собственной среде Python 3 на вымышленных данных, без личных файлов и секретов. В ответе отделяйте реально выполненные проверки от плана тестирования."],"example":"Итоговый пакет: app.py + функции расчёта + учебный JSON + тесты + README.\nREADME: установка Python3, команда запуска, формат копеек, пример отчёта, ограничения и способ резервного копирования.","task":"Представьте итоговый трекер: код или подробную спецификацию с ключевыми фрагментами, загрузка/сохранение JSON, отчёт по категориям, обработка ошибок и пять тестов. Приложите инструкцию и явно отделите проверенный функционал от плана.","criteria":["Есть проверка схемы и безопасная загрузка/запись","Работают расчёты и отчёт, предусмотрен перезапуск","Приложены пять тестов, инструкция и честные ограничения"],"question":"Что показывает готовность итогового проекта?","options":["Рабочий сценарий, тесты и понятная инструкция","Только длинный код","Обещание автора, что ошибок нет"],"correct":0,"explanation":"Готовность подтверждается воспроизводимым поведением и проверками, а не размером программы."}]}]},{"id":"design","title":"Дизайн и визуальный вкус","category":"Дизайн","level":"С нуля","duration":"6 уроков · ~2,5 часа","color":"violet","symbol":"Aa","description":"Научитесь видеть, почему интерфейс работает: иерархия, цвет, типографика и ваш первый осмысленный макет вместо случайных украшений.","outcome":"Проект первого экрана учебного сервиса с обоснованием решений и проверкой доступности.","skills":["Композиция","Типографика","Доступность"],"modules":[{"title":"Смысл и композиция","lessons":[{"id":"1","title":"От задачи к дизайн-брифу","theory":["Дизайн помогает человеку выполнить действие. Бриф отвечает на четыре вопроса: кто пользователь, какая у него задача, что мешает и какое действие считается успехом. «Сделать красиво» — не измеримая задача.","Не подменяйте исследование догадками. Для учебного проекта допустимы гипотезы, но помечайте их. Уточните контекст: человек открывает страницу с телефона между занятиями или внимательно сравнивает варианты за компьютером?"],"example":"До: «Сделать страницу курса».\nПосле: «Студент с телефона за минуту понимает, чему научится, сколько займёт курс и где начать бесплатный урок. Проверяем, может ли он найти кнопку без подсказки».","task":"Составьте бриф первого экрана сервиса изучения языков: аудитория, ситуация использования, одно главное действие и способ проверки успеха.","criteria":["Названы аудитория и конкретная ситуация","Выбрано одно главное действие","Есть проверяемый критерий успеха, гипотезы помечены"],"question":"Какой критерий полезнее для брифа?","options":["Выглядит модно","Пользователь находит начало урока без подсказки","На странице пять цветов"],"correct":1,"explanation":"Критерий описывает действие человека, а не вкусовую оценку.","minutes":20},{"id":"2","title":"Визуальная иерархия и отступы","theory":["Иерархия показывает порядок чтения: заголовок объясняет ценность, пояснение снимает вопрос, кнопка предлагает действие. Размер, насыщенность, положение и свободное место помогают различать главное и второстепенное.","Близкие по смыслу элементы располагайте ближе друг к другу. Один ритм отступов делает интерфейс связным. Если всё одинаково крупное и яркое, акцента нет. Проверяйте макет в уменьшении: видно ли главное?"],"example":"До: цена, заголовок, отзывы и три кнопки одинакового размера.\nПосле: крупное обещание результата → короткое объяснение → одна основная кнопка. Отзывы ниже и спокойнее.","task":"Опишите или нарисуйте схему первого экрана из пяти элементов. Укажите порядок чтения, один главный акцент и правила расстояний между группами.","criteria":["Порядок чтения явно указан","Главный акцент только один","Отступы объединяют связанные элементы"],"question":"Что происходит, если все кнопки одинаково яркие?","options":["Выбор становится менее очевидным","Появляется один главный акцент","Автоматически растёт доступность"],"correct":0,"explanation":"Равные акценты конкурируют за внимание.","minutes":20}]},{"title":"Текст и цвет","lessons":[{"id":"3","title":"Типографика, которая помогает читать","theory":["Типографика — это не только выбор шрифта. Важны размер, интерлиньяж, длина строки и различие уровней. Для основного текста веб-интерфейса 16 px — полезная стартовая точка, но итог проверяют на реальном устройстве.","Не набирайте длинные абзацы капсом и не используйте слишком тонкое начертание для мелкого текста. Создайте шкалу ролей: заголовок, подзаголовок, основной текст, подпись. Сохраните читаемость при увеличении масштаба до 200%."],"example":"Шкала-пример: H1 36/42, H2 24/30, текст 16/24, подпись 14/20. До: абзац длиной во весь экран. После: ограниченная ширина и короткие смысловые абзацы.","task":"Предложите четыре текстовых стиля для страницы курса. Укажите размер и межстрочное расстояние, затем опишите проверку на телефоне и при увеличении масштаба.","criteria":["Есть четыре роли, а не случайные размеры","Для каждой роли задан интерлиньяж","Предусмотрены телефон и масштаб 200%"],"question":"Что помогает читать длинное объяснение?","options":["Капс и узкий интерлиньяж","Сплошной абзац без границ","Умеренная длина строки и достаточный интерлиньяж"],"correct":2,"explanation":"Читателю проще находить начало следующей строки.","minutes":20},{"id":"4","title":"Цвет и доступность","theory":["У цвета должна быть роль: фон, текст, главное действие, ошибка, успех. Не используйте цвет как единственный сигнал: красная рамка без текста ошибки не объясняет проблему и может быть незаметна человеку с особенностями цветовосприятия.","Для обычного текста WCAG AA требует контраст не менее 4,5:1; для крупного — 3:1. Проверяйте конкретную пару переднего плана и фона инструментом контраста. Сам цвет по названию не гарантирует читаемость."],"example":"До: ошибка обозначена только красной точкой.\nПосле: значок + текст «Введите адрес в формате name@example.com» + заметная рамка. Цвет помогает, но смысл доступен без него.","task":"Задайте палитру из пяти ролей с HEX-кодами. Опишите пару текст/фон, способ измерения контраста и оформление ошибки без опоры только на цвет.","criteria":["Цвета связаны с ролями","Указан порог 4,5:1 для обычного текста и способ проверки","Ошибка понятна без различения цвета"],"question":"Достаточно ли сделать ошибку красной?","options":["Нет, нужен ещё понятный текст или другой сигнал","Да, красный видят все","Только на большом экране"],"correct":0,"explanation":"Цвет не должен быть единственным носителем информации.","minutes":20}]},{"title":"Система и макет","lessons":[{"id":"5","title":"Компоненты и состояния","theory":["Компонент — повторяемый элемент с правилами. У кнопки есть размер, подпись и состояния: обычное, наведение, фокус, нажатие, недоступность. Фокус показывает, где находится пользователь клавиатуры; его нельзя просто убрать ради красоты.","Карточки должны сохранять структуру при длинном заголовке и отсутствии изображения. Систему проверяют не только на идеальных данных: нужны загрузка, пустой результат и ошибка. Адаптация — перестройка, а не уменьшенная копия десктопа."],"example":"Карточка: название → длительность → результат → действие.\nПустой поиск: «Ничего не найдено. Попробуйте другой запрос» + сброс фильтра.\nКнопка в фокусе: видимый контур, не только смена оттенка.","task":"Опишите компонент карточки курса и основной кнопки. Добавьте состояния фокуса, загрузки и пустого каталога. Объясните перестройку карточки на ширине 375 px.","criteria":["Есть повторяемая структура карточки","Учтены фокус, загрузка и пустой результат","На телефоне не теряются текст и действие"],"question":"Зачем нужен видимый фокус?","options":["Для выбора фирменного цвета","Чтобы ориентироваться при навигации клавиатурой","Чтобы увеличить число кнопок"],"correct":1,"explanation":"Фокус делает управление с клавиатуры понятным.","minutes":20},{"id":"6","title":"Итог: первый экран сервиса","theory":["Финальный макет объединяет бриф, иерархию и систему. Можно отправить текстовую спецификацию или описание собственного макета: платный редактор не нужен. Важнее объяснить, как решение помогает конкретному пользователю.","Проведите короткую проверку: покажите макет человеку и спросите, чему посвящён сервис и куда нажать для начала. Не подсказывайте. Запишите проблему и одну доработку. Если тест пока не проведён, честно укажите план, не выдумывайте отзывы."],"example":"Обоснование: «Главная кнопка одна, потому что цель — начать урок. Под ней длительность, снимающая страх нехватки времени. На телефоне блоки идут в смысловом порядке».","task":"Подготовьте первый экран учебного сервиса: бриф, схема блоков, стили текста, палитра, состояния кнопки и мобильная версия. Добавьте отчёт о тесте или честный план и одну гипотезу улучшения.","criteria":["Решения связаны с задачей и одним главным действием","Описаны типографика, контраст и мобильное поведение","Есть проверка с наблюдением или явно обозначенный план без выдуманных данных"],"question":"Что лучше обосновывает дизайн?","options":["Так сейчас делают все","Мне нравится этот цвет","Решение помогает целевому пользователю выполнить задачу"],"correct":2,"explanation":"Дизайн оценивается относительно задачи, а не только личного вкуса.","minutes":40}]}]},{"id":"sql","title":"SQL и базы данных","category":"Данные","level":"С нуля","duration":"6 уроков · ~2,5 часа","color":"amber","symbol":"DB","description":"От вопроса к данным — до проверенного отчёта. Научитесь фильтровать, считать и связывать таблицы, понимая смысл каждой строки.","outcome":"Набор SQL-запросов для учебного отчёта о заказах с объяснением метрик и проверкой итогов.","skills":["SELECT","JOIN","Агрегация"],"modules":[{"title":"Данные и выборка","lessons":[{"id":"1","title":"Таблица и SELECT","theory":["Реляционная таблица состоит из строк и столбцов. Каждая строка — наблюдение, например заказ. Ключ id отличает записи; одинаковое имя покупателя ключом не является. SQL описывает, какие данные нужны, а не как вручную перебирать строки.","В курсе используем учебную схему orders(id, customer_id, amount, status) и customers(id, name, city). Запросы в интерфейсе не исполняются. Примеры соответствуют базовому SQL/PostgreSQL; проверьте их в собственной учебной базе без реальных персональных данных."],"example":"Учебные orders:\n1 | 10 | 500 | paid\n2 | 11 | 300 | cancelled\n3 | 10 | 700 | paid\n\nSELECT id, amount FROM orders;\n-- 1,500; 2,300; 3,700. Порядок без ORDER BY не гарантирован.","task":"Напишите запрос к orders, выводящий id, customer_id и status. Объясните, почему лучше перечислить столбцы, чем использовать SELECT * в отчёте.","criteria":["Есть SELECT с тремя указанными столбцами","Названа таблица orders через FROM","Объяснена устойчивость явного списка столбцов"],"question":"Что задаёт FROM?","options":["Сортировку","Источник данных","Количество столбцов"],"correct":1,"explanation":"FROM указывает таблицу или другой источник выборки.","minutes":20},{"id":"2","title":"WHERE и ORDER BY","theory":["WHERE оставляет строки, соответствующие условию. AND требует выполнения обоих условий, OR — хотя бы одного. Текстовые значения пишут в одинарных кавычках. Сравнение с отсутствующим значением делают через IS NULL, а не = NULL.","ORDER BY задаёт порядок, DESC — по убыванию. При равных суммах добавьте id для устойчивого порядка. LIMIT ограничивает количество строк, но без ORDER BY нельзя рассчитывать на «самые большие» или «самые новые»."],"example":"SELECT id, amount\nFROM orders\nWHERE status = 'paid' AND amount >= 500\nORDER BY amount DESC, id ASC;\n-- 3,700; 1,500","task":"Получите оплаченные заказы с суммой от 600, отсортируйте по убыванию суммы и затем по id. Ограничьте результат пятью строками. Назовите ожидаемый id для учебных данных.","criteria":["Фильтр использует status и amount с AND","Есть устойчивая сортировка и LIMIT 5","Ожидаемый результат содержит id 3"],"question":"Как проверить отсутствующее значение?","options":["city = NULL","city IS NULL","city = 'NULL'"],"correct":1,"explanation":"NULL обозначает отсутствие значения, его проверяют IS NULL.","minutes":20}]},{"title":"Расчёты и группировки","lessons":[{"id":"3","title":"SUM, COUNT и средние","theory":["Агрегат сворачивает строки в показатель: SUM(amount) — сумма, COUNT(*) — число строк, AVG(amount) — среднее известных сумм. COUNT(amount) не учитывает NULL, в отличие от COUNT(*). Значение показателя зависит от фильтра.","Перед расчётом определите смысл: выручка — сумма только оплаченных заказов, а не всех созданных. На пустой выборке COUNT даёт 0, но SUM обычно NULL; COALESCE(SUM(amount), 0) заменяет его нулём для отчёта."],"example":"SELECT COUNT(*) AS paid_orders,\n       COALESCE(SUM(amount), 0) AS revenue,\n       AVG(amount) AS avg_order\nFROM orders\nWHERE status = 'paid';\n-- 2 заказа, 1200 сумма, 600 среднее","task":"Составьте запрос количества и суммы оплаченных заказов. Назовите результаты для учебных данных и объясните, что произойдёт с SUM без COALESCE на пустой выборке.","criteria":["Отменённые заказы исключены","Показатели подписаны через AS","Верно указаны 2, 1200 и поведение NULL на пустой выборке"],"question":"Что считает COUNT(*)?","options":["Все строки выборки","Только ненулевые суммы","Только уникальных клиентов"],"correct":0,"explanation":"COUNT(*) считает строки, включая строки с NULL в отдельных столбцах.","minutes":20},{"id":"4","title":"GROUP BY и HAVING","theory":["GROUP BY считает показатель отдельно для каждой группы. Если в SELECT есть обычный столбец и агрегат, обычный столбец должен участвовать в группировке. Для каждого customer_id получится своя сумма.","WHERE фильтрует строки до группировки, HAVING — группы после расчёта. Это разные этапы. Условие SUM(amount) > 1000 размещают в HAVING, а status = 'paid' — в WHERE."],"example":"SELECT customer_id, SUM(amount) AS revenue\nFROM orders\nWHERE status = 'paid'\nGROUP BY customer_id\nHAVING SUM(amount) > 1000;\n-- customer_id 10, revenue 1200","task":"Получите клиентов, у которых не меньше двух оплаченных заказов. Выведите customer_id и число заказов, отсортируйте число по убыванию. Опишите роль WHERE и HAVING.","criteria":["Группировка по customer_id","HAVING COUNT(*) >= 2 после фильтра paid","Объяснён порядок фильтрации строк и групп"],"question":"Где фильтровать по SUM(amount)?","options":["В FROM","В WHERE до группировки","В HAVING"],"correct":2,"explanation":"Агрегат существует после группировки, поэтому его условие относится к HAVING.","minutes":20}]},{"title":"Связи и отчёт","lessons":[{"id":"5","title":"JOIN без потери смысла","theory":["JOIN соединяет строки по условию. Для заказов и клиентов связь orders.customer_id = customers.id. INNER JOIN оставляет совпадения; LEFT JOIN сохраняет все строки слева, даже если соответствия нет.","Проверяйте кардинальность: если ключ справа не уникален, один заказ может повториться, и сумма вырастет ошибочно. Не соединяйте по имени клиента. Фильтр по правой таблице в WHERE после LEFT JOIN может убрать строки с NULL."],"example":"SELECT o.id, c.name, o.amount\nFROM orders AS o\nJOIN customers AS c ON o.customer_id = c.id;\n-- customers: 10 | Ира | Казань; 11 | Олег | Омск","task":"Напишите запрос всех клиентов и их заказов, включая клиентов без заказов. Выведите c.id, c.name, o.id. Объясните, почему выбрана левая таблица и как выглядит отсутствие заказа.","criteria":["customers стоит слева от LEFT JOIN","Связь построена по c.id = o.customer_id","Для отсутствующего заказа ожидается NULL, а не 0"],"question":"Как сохранить клиентов без заказов?","options":["customers LEFT JOIN orders","orders INNER JOIN customers","Соединить по имени"],"correct":0,"explanation":"LEFT JOIN сохраняет все строки левой таблицы customers.","minutes":20},{"id":"6","title":"Итог: отчёт о заказах","theory":["Хороший отчёт начинается с определений. Здесь выручка — сумма amount у status = 'paid'; период в учебной схеме не задан, поэтому не называйте отчёт месячным. Источник и ограничения важнее красивого числа.","Сделайте три отдельных запроса: общая выручка, показатели по клиентам и список лидеров. Контроль: сумма клиентских итогов должна совпасть с общей при полном и корректном соединении. Не запускайте UPDATE или DELETE для этой задачи."],"example":"Контроль: paid = 500 + 700 = 1200.\nКлиент 10: 2 оплаченных заказа, 1200.\nКлиент 11: 0 оплаченных заказов. При сохранении всех клиентов используйте LEFT JOIN с фильтром paid в ON.","task":"Подготовьте три SQL-запроса: общие показатели paid, оплаченные итоги каждого клиента (включая нулевые), топ-3 клиента по сумме. Приложите определение выручки и ручную проверку на учебном наборе.","criteria":["Есть три читаемых запроса с правильными связями и фильтрами","Клиенты без paid сохранены, NULL суммы обработан","Приведены ручные итоги 1200 и объяснение ограничений схемы"],"question":"Почему после JOIN сумма могла вырасти?","options":["SUM всегда округляет вверх","Появились дубли из связи один-ко-многим","ORDER BY меняет значения"],"correct":1,"explanation":"Неожиданное размножение строк при соединении искажает агрегаты.","minutes":40}]}]},{"id":"web","title":"Создание сайтов без скучной теории","category":"Разработка","level":"С нуля","duration":"6 уроков · ~2,5 часа","color":"coral","symbol":"</>","description":"Учитесь через свой сайт: соберите страницу, сделайте её удобной на телефоне и добавьте первое живое взаимодействие.","outcome":"Одностраничный сайт-портфолио с мобильной версией, доступной навигацией и работающим взаимодействием.","skills":["HTML","CSS","JavaScript"],"modules":[{"title":"Структура страницы","lessons":[{"id":"1","title":"Семантический HTML","theory":["HTML описывает смысл содержимого. Заголовки h1–h6 создают иерархию, main обозначает основное содержимое, nav — навигацию. Для действия используйте button, для перехода — a с href.","Документу нужны doctype, lang, кодировка и title. Картинке нужен alt, описывающий её функцию; декоративному изображению — пустой alt. Код курса хранится как текст и не исполняется здесь: сохраните его в локальный index.html."],"example":"<!doctype html>\n<html lang=\"ru\">\n<head><meta charset=\"UTF-8\"><title>Портфолио Лены</title></head>\n<body><header><a href=\"#projects\">Проекты</a></header>\n<main><h1>Лена — начинающий дизайнер</h1><section id=\"projects\"><h2>Мои проекты</h2><p>Первый учебный макет</p></section></main></body>\n</html>","task":"Напишите каркас портфолио с lang='ru', title, одним h1, разделом проектов с h2 и ссылкой на него. Объясните разницу ссылки и кнопки.","criteria":["Есть метаданные и семантический main","Ссылка ведёт к существующему id","Иерархия заголовков и роли ссылки/кнопки объяснены"],"question":"Что лучше для перехода к другой странице?","options":["div с текстом","a с href","button без обработчика"],"correct":1,"explanation":"Ссылка поддерживает переходы, открытие в новой вкладке и привычную навигацию.","minutes":20},{"id":"2","title":"Контент и доступная форма","theory":["Поле формы должно иметь label, связанный через for и id. Placeholder не заменяет подпись: он исчезает при вводе. Для адреса используйте type='email', для обязательного поля — required.","Форма без сервера не отправит сообщение владельцу. Не показывайте «отправлено», если запроса не было. В учебной версии честно покажите локальный результат или способ связи без отправки. Ошибку формулируйте как инструкцию к исправлению."],"example":"<form id=\"demo-form\">\n<label for=\"email\">Ваш email</label>\n<input id=\"email\" name=\"email\" type=\"email\" required>\n<button type=\"submit\">Проверить ввод (демо)</button>\n<p role=\"status\">Сообщение никуда не отправляется</p>\n</form>","task":"Создайте учебную форму email и имени с постоянными подписями. Добавьте пояснение, что данные не отправляются. Опишите поведение для пустого и неверного email.","criteria":["У каждого поля есть связанный label","Проверяются обязательность и формат email","Нет ложного обещания серверной отправки"],"question":"Заменяет ли placeholder постоянный label?","options":["Да, если он серый","Только на телефоне","Нет, подпись должна оставаться доступной"],"correct":2,"explanation":"Placeholder исчезает при вводе и не выполняет роль постоянной подписи.","minutes":20}]},{"title":"Стиль и адаптация","lessons":[{"id":"3","title":"CSS и блочная модель","theory":["CSS задаёт оформление через селекторы. Блочная модель состоит из содержимого, padding, border и margin. box-sizing: border-box включает padding и border в заданную ширину, делая расчёты понятнее.","Класс переиспользуется для нескольких элементов. Не привязывайте всё к случайным id и не исправляйте каждый конфликт через !important. Начните с базового текста, ограничения ширины и ритма отступов."],"example":"* { box-sizing: border-box; }\nbody { margin: 0; font: 16px/1.5 system-ui; color: #172b25; background: #f2f7f4; }\nmain { max-width: 960px; margin: auto; padding: 24px; }\n.card { padding: 20px; border: 1px solid #9bb4a7; border-radius: 16px; }","task":"Напишите стили страницы и карточки проекта: ограничение ширины, удобный текст, внутренние и внешние отступы. Объясните, какие части ширины включает border-box.","criteria":["Задан box-sizing и читаемый основной текст","Карточка использует класс и осмысленные отступы","Объяснена разница padding и margin"],"question":"Что делает padding?","options":["Добавляет внутренний отступ","Удаляет рамку","Задаёт адрес ссылки"],"correct":0,"explanation":"Padding отделяет содержимое от внутренней границы блока.","minutes":20},{"id":"4","title":"Адаптивная сетка","theory":["Адаптивный сайт подстраивается под доступное место. Мета-тег viewport сообщает мобильному браузеру использовать ширину устройства. Grid и media queries позволяют менять число колонок без фиксированной ширины всей страницы.","Проверяйте не только типовые устройства, но и промежуточную ширину. Изображения ограничьте max-width:100%. Длинный текст не должен создавать горизонтальную прокрутку. Смысловой порядок HTML сохраняйте при перестроении."],"example":"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n.projects { display: grid; gap: 20px; grid-template-columns: 1fr; }\nimg { max-width: 100%; height: auto; }\n@media (min-width: 700px) { .projects { grid-template-columns: repeat(2, minmax(0, 1fr)); } }","task":"Сделайте сетку проектов: одна колонка на телефоне, две от 700 px. Добавьте viewport и защиту изображений от переполнения. Опишите проверки на 375 и 900 px.","criteria":["Есть viewport и mobile-first одна колонка","Медиаусловие включает две колонки","Проверены длинный текст и отсутствие горизонтального скролла"],"question":"Что делает media query?","options":["Меняет HTML-файл на сервере","Применяет CSS при определённых условиях","Сохраняет данные формы"],"correct":1,"explanation":"Условие может зависеть от ширины экрана или пользовательских предпочтений.","minutes":20}]},{"title":"Поведение и запуск","lessons":[{"id":"5","title":"JavaScript и безопасный DOM","theory":["JavaScript связывает действие и изменение состояния. querySelector находит элемент, addEventListener подписывается на событие. Если скрипт обращается к DOM до его создания, элемент будет null; используйте defer или ставьте скрипт после разметки.","Для пользовательского текста используйте textContent, а не innerHTML: чужая строка не должна превращаться в исполняемую разметку. Кнопка должна работать клавиатурой, поэтому не заменяйте её кликабельным div."],"example":"<button id=\"hello\">Показать приветствие</button><p id=\"result\" role=\"status\"></p>\n<script>\nconst button = document.querySelector('#hello');\nbutton.addEventListener('click', () => {\n  document.querySelector('#result').textContent = 'Спасибо за интерес к моим проектам!';\n});\n</script>","task":"Добавьте кнопку, которая показывает краткий рассказ о проекте в области role='status'. Используйте addEventListener и textContent. Опишите проверку кликом и клавишами Tab/Enter.","criteria":["Есть настоящая button и обработчик события","Текст вставляется через textContent","Описана клавиатурная проверка и доступное сообщение"],"question":"Как безопасно вывести введённое имя как текст?","options":["Через innerHTML без обработки","Выполнить eval(name)","Через textContent"],"correct":2,"explanation":"textContent не интерпретирует строку как HTML.","minutes":20},{"id":"6","title":"Итог: своё портфолио","theory":["Соберите страницу, которая отвечает на три вопроса: кто вы, что умеете, где посмотреть результат. Учебный проект можно честно назвать учебным. Не используйте чужие работы как свои.","Перед готовностью проверьте ссылки, клавиатуру, мобильную сетку и сообщения формы. Открыть файл локально достаточно для курса; публикация и платный хостинг не требуются. Если связь не подключена, обозначьте это явно."],"example":"Чек-лист выпуска: index.html открывается → все якоря существуют → 375 px без переполнения → Tab показывает фокус → кнопка обновляет текст → форма не обещает несуществующую отправку.","task":"Отправьте HTML/CSS/JS портфолио или подробную спецификацию с фрагментами кода. Нужны представление, два проекта, адаптивная сетка и одно работающее взаимодействие. Приложите результаты ручных проверок.","criteria":["Есть семантические разделы и честное описание двух проектов","Адаптация и доступная клавиатурная навигация проверены","Взаимодействие работает, нет ложного сообщения об отправке"],"question":"Что обязательно проверить перед готовностью страницы?","options":["Только размер заголовка","Ссылки, мобильную версию и управление клавиатурой","Только цвет фона"],"correct":1,"explanation":"Готовность — это поведение в реальных сценариях, а не только оформление.","minutes":40}]}]},{"id":"analytics","title":"Аналитика данных на практике","category":"Данные","level":"Начальный","duration":"6 уроков · ~2,5 часа","color":"cyan","symbol":"Σ","description":"Разберите учебную кампанию как аналитик: очистите данные, посчитайте показатели и предложите решение с честными ограничениями.","outcome":"Краткий аналитический отчёт о учебной кампании: показатели, ограничения и обоснованная рекомендация.","skills":["Метрики","Качество данных","Выводы"],"modules":[{"title":"Вопрос и качество данных","lessons":[{"id":"1","title":"Вопрос прежде таблицы","theory":["Аналитика начинается с решения, которое нужно принять. «Посмотреть данные» не задаёт направления. «Какой канал стоит проверить в следующей кампании при ограниченном бюджете?» связывает расчёт с действием.","Определите единицу наблюдения и период. Строка может обозначать человека, сессию или заказ: смешивание этих уровней искажает показатели. В курсе используем вымышленную кампанию: A — 1000 визитов, 50 заявок, 10000 ₽; B — 500 визитов, 40 заявок, 12000 ₽. Заявка не означает продажу."],"example":"Вопрос: какой канал эффективнее привлекает заявки?\nЕдиница отчёта: канал за одинаковые 7 дней.\nМетрики: конверсия в заявку и стоимость заявки.\nОграничение: качество заявок и продажи пока неизвестны.","task":"Сформулируйте вопрос для учебного отчёта по A и B. Укажите решение, период, единицу строки, две метрики и недостающие сведения.","criteria":["Вопрос связан с конкретным решением","Определены период и единица наблюдения","Метрики отделены от неизвестных продаж и качества"],"question":"Что сначала определяют в аналитической задаче?","options":["Цвет диаграммы","Вопрос и решение, которому поможет ответ","Название файла"],"correct":1,"explanation":"Вопрос задаёт, какие данные и расчёты действительно нужны.","minutes":20},{"id":"2","title":"Проверка качества данных","theory":["Проверьте дубли, пропуски, типы и диапазоны до расчёта. Ноль и отсутствие значения — разные вещи: 0 заявок означает известный результат, пустая ячейка может означать сбой сбора. Заменять всё пустое нулём опасно.","Правило удаления дублей зависит от ключа. Две одинаковые суммы не обязательно повтор: это могут быть разные заказы. Сохраняйте исходный набор и отдельно фиксируйте очистку, чтобы решение можно было воспроизвести."],"example":"id | канал | заявки\n101 | A | 5\n101 | A | 5  ← проверить дубль по id\n102 | B | пусто ← уточнить сбор, не заменять молча на 0\n103 | B | -2 ← недопустимое значение счётчика","task":"Предложите правила очистки показанного набора. Опишите обработку повторного id, пропуска и отрицательных заявок, а также журнал изменений.","criteria":["Дубликат проверяется по ключу и контексту","Пропуск не подменён нулём без основания","Исходник сохранён, спорные строки и изменения зафиксированы"],"question":"Всегда ли пустая ячейка равна нулю?","options":["Да","Нет, причина отсутствия требует проверки","Только в CSV"],"correct":1,"explanation":"Пропуск может говорить о неизвестном результате или проблеме сбора.","minutes":20}]},{"title":"Расчёты и интерпретация","lessons":[{"id":"3","title":"Конверсия и стоимость результата","theory":["Конверсия в заявку = заявки / визиты × 100%. Стоимость заявки CPL = расходы / заявки. Числитель и знаменатель должны относиться к одному периоду и одному определению события.","Для A конверсия 50/1000 = 5%, CPL 10000/50 = 200 ₽. Для B конверсия 40/500 = 8%, CPL 12000/40 = 300 ₽. Более высокая конверсия не обязательно означает более дешёвый результат. При нуле заявок CPL не определён, делить на ноль нельзя."],"example":"A: CR 5%, CPL 200 ₽.\nB: CR 8%, CPL 300 ₽.\nВывод: B лучше конвертирует визиты, но A дешевле по заявке. Данных о стоимости продажи нет.","task":"Покажите формулы и расчёты CR/CPL для обоих каналов. Объясните противоречие и правило для нуля заявок.","criteria":["CR равны 5% и 8%, CPL — 200 и 300 ₽","Формулы используют правильные знаменатели","Ноль обработан явно, вывод не приравнивает заявки к продажам"],"question":"Как считается CPL?","options":["Заявки / визиты","Расходы / заявки","Визиты / расходы"],"correct":1,"explanation":"CPL показывает стоимость одной заявки, а не долю визитов.","minutes":20},{"id":"4","title":"Среднее и честное сравнение","theory":["Среднее долей нельзя бездумно усреднять. Общая конверсия A+B = (50+40)/(1000+500) = 6%, а не (5%+8%)/2 = 6,5%. Каналы имеют разное число визитов и должны иметь разный вес.","Сравнение требует одинаковых определений и сопоставимой аудитории. Разница в устройстве, сезоне или качестве трафика может объяснять показатели. Наблюдаемая связь не доказывает, что смена канала сама вызовет рост результата."],"example":"Общий CR: 90 / 1500 × 100 = 6%.\nОбщий CPL: 22000 / 90 ≈ 244,44 ₽.\nНельзя получить общий CPL простым средним 200 и 300: заявок было разное количество.","task":"Рассчитайте общие CR и CPL учебной кампании. Объясните ошибку простого среднего и назовите два фактора, мешающих прямому сравнению.","criteria":["Общий CR 6%, CPL около 244,44 ₽","Объяснены разные веса каналов","Названы два возможных смешивающих фактора"],"question":"Какой общий CR у A и B?","options":["6,5%","13%","6%"],"correct":2,"explanation":"Нужно разделить суммарные заявки на суммарные визиты.","minutes":20}]},{"title":"Эксперимент и решение","lessons":[{"id":"5","title":"Гипотеза и эксперимент","theory":["Гипотеза связывает изменение, ожидаемый эффект и измерение. Например: «Уточнение первого экрана повысит долю заявок, не снижая их качество». Для проверки заранее определите основную метрику и защитную, например качество заявки.","A/B-тест предполагает случайное распределение сопоставимых пользователей и стабильный учёт. Не завершайте тест при первом удобном результате и не объявляйте значимость по разнице процентов без расчёта. Для учебного плана можно описать метод без выдуманного размера выборки."],"example":"Гипотеза: ясное описание результата курса уменьшит непонимание предложения.\nОсновная метрика: CR в заявку.\nЗащитная: доля подходящих заявок.\nПлан: случайное распределение, одинаковый период, заранее выбранные критерии анализа.","task":"Составьте план проверки улучшения страницы канала A. Укажите изменение, основную и защитную метрики, распределение участников и условие завершения без подглядывания.","criteria":["Меняется один осмысленный фактор","Метрики и случайное распределение заданы заранее","Нет обещания значимости без данных и расчёта"],"question":"Доказывает ли разница 5% и 8% причину?","options":["Нет, нужен корректный дизайн проверки","Да, любой больший процент доказывает","Да, если округлить"],"correct":0,"explanation":"На результат могут влиять аудитория и другие факторы; причинность требует отдельной проверки.","minutes":20},{"id":"6","title":"Итог: отчёт и рекомендация","theory":["Структура отчёта: вопрос → источник и качество → метод → результаты → ограничения → действие. Показывайте расчёты так, чтобы другой человек мог их повторить. Если график не нужен, компактной таблицы достаточно.","Рекомендация должна учитывать неизвестное. Для учебных данных разумно тестировать A как более дешёвый источник заявок, параллельно измеряя качество; это не обещание более дешёвых продаж. Указывайте, какой факт изменит решение."],"example":"Кратко: A — CPL 200 ₽, B — 300 ₽; CR выше у B. Предлагаем ограниченный тест A и учёт подходящих заявок. Решение пересмотрим, если качество A окажется заметно ниже. Данные вымышленные, период одинаковый.","task":"Подготовьте отчёт по A и B: вопрос, проверка данных, формулы, таблица показателей, ограничения и одно следующее действие. Добавьте факт, при котором измените рекомендацию.","criteria":["Все четыре показателя и общие итоги рассчитаны верно","Указаны вымышленный источник и ограничения причинных выводов","Рекомендация конкретна и содержит условие пересмотра"],"question":"Какая рекомендация честнее?","options":["Всегда переносить весь бюджет в A","Проверить A ограниченным тестом и измерить качество заявок","Объявить B убыточным без данных о продажах"],"correct":1,"explanation":"Дешёвая заявка ещё не доказывает прибыльность, поэтому нужен ограниченный и измеримый следующий шаг.","minutes":40}]}]},{"id":"soft-skills","title":"Самопрезентация и личный бренд","category":"Карьера","level":"Для всех","duration":"6 уроков · ~2,5 часа","color":"rose","symbol":"Hi","description":"Соберите ясный рассказ о себе и сильных сторонах. Покажите свой вклад, подготовьте самопрезентацию и выстройте доверие без выдуманных достижений.","outcome":"Самопрезентация на 60 секунд, история по STAR и план разговора о своём следующем шаге.","skills":["Коммуникация","STAR","Обратная связь"],"modules":[{"title":"Сильные стороны и рассказ","lessons":[{"id":"1","title":"Навыки через доказательства","theory":["Фраза «я ответственный» не показывает, как вы действуете. Выберите ситуацию, действие и наблюдаемый результат. Учебный, волонтёрский или личный проект подходит, если вы честно обозначаете свой вклад.","Не нужно придумывать проценты или профессиональный опыт. Если точной метрики нет, опишите проверяемый результат: команда сдала работу вовремя, инструкция помогла новичку выполнить задачу, прототип прошёл пробный показ."],"example":"До: «Я лидер и умею работать в команде».\nПосле: «В учебной команде из четырёх человек собрал список задач и договорился о контрольной встрече. Мы сдали проект в срок. Мой вклад — организация и сбор материалов».","task":"Назовите две свои сильные стороны. Для каждой опишите реальную ситуацию, личное действие и результат. Если опыта мало, используйте учебный пример без выдуманных цифр.","criteria":["Для двух навыков приведены конкретные ситуации","Личный вклад отделён от результата всей команды","Нет неподтверждённых достижений и выдуманных метрик"],"question":"Что убедительнее при описании навыка?","options":["Я очень коммуникабельный","Конкретное действие и проверяемый результат","Список модных качеств"],"correct":1,"explanation":"Пример позволяет понять, как навык проявился на деле.","minutes":20},{"id":"2","title":"Самопрезентация на 60 секунд","theory":["Короткий рассказ о себе отвечает на вопросы: кто вы сейчас, что умеете с доказательством, куда хотите двигаться и чем можете быть полезны. Он зависит от аудитории: для команды проекта важны одни детали, для стажировки — другие.","Не превращайте минуту в полную биографию. Прочитайте текст вслух с таймером, уберите повторения и жаргон. Не обещайте знать всё: ясная зона развития звучит надёжнее завышенных ожиданий."],"example":"«Я студент и начинающий аналитик. В учебном проекте очистил таблицу заявок и показал, где теряются данные. Ищу команду для практики отчётности; могу взять проверку данных и документацию. Сейчас углубляю SQL».","task":"Напишите самопрезентацию для выбранной стажировки или команды. Укажите аудиторию, текущую роль, один пример навыка и конкретное предложение. Отметьте время чтения вслух.","criteria":["Рассказ адресован конкретной аудитории","Есть пример и понятный запрос или предложение","Длительность проверена таймером, нет лишней биографии"],"question":"Что стоит убрать из минутного рассказа?","options":["Один релевантный пример","Понятную цель","Полную хронологию всех занятий"],"correct":2,"explanation":"Короткая презентация требует отбора того, что важно этой аудитории.","minutes":20}]},{"title":"Диалог и обратная связь","lessons":[{"id":"3","title":"Активное слушание и уточнение","theory":["Слушать — значит проверять понимание, а не ждать своей очереди. Сначала перефразируйте услышанное, затем уточните неопределённость. Открытый вопрос помогает раскрыть контекст; закрытый полезен для фиксации договорённости.","Не выдавайте свою догадку за намерение собеседника. Вместо «вам всё равно» спросите «что мешает выбрать срок?». В конце назовите, кто и что делает дальше, и попросите подтвердить."],"example":"Собеседник: «Нужно побыстрее переделать слайды».\nОтвет: «Правильно понимаю, главное — подготовить их к пятнице? Для какой аудитории и какие два изменения важнее всего? Я пришлю черновик завтра до 16:00 — подходит?»","task":"Ответьте на сообщение «Сделай нормально отчёт, он нужен срочно». Перефразируйте запрос, задайте три уточнения и предложите проверяемую договорённость.","criteria":["Нет обвинения или угадывания чужих мотивов","Уточнены цель, качество и срок","Названы следующий результат и способ подтверждения"],"question":"Какая фраза проверяет понимание?","options":["Вы опять не объяснили","Я и так знаю, что вам нужно","Правильно понимаю, что главное — ...?"],"correct":2,"explanation":"Перефразирование даёт человеку возможность подтвердить или поправить смысл.","minutes":20},{"id":"4","title":"Обратная связь без нападения","theory":["Полезная обратная связь отделяет наблюдение от оценки личности. Укажите ситуацию, конкретное поведение и влияние; затем обсудите желаемый следующий шаг. «Ты безответственный» — ярлык, «вчера файл пришёл после согласованного срока» — наблюдение.","Получая обратную связь, попросите пример и ожидаемый результат. Можно не согласиться с интерпретацией, сохранив уважение. Для чувствительной темы выберите личный разговор, а не публичное обсуждение."],"example":"«На вчерашней встрече я не получил список изменений к сроку. Из-за этого не успел собрать версию. Давай договоримся: если срок сдвигается, предупреждаем за два часа и называем новый».","task":"Перепишите «Ты постоянно всё портишь, с тобой невозможно работать» в конкретную обратную связь. Добавьте вопрос о причинах и предложение следующего шага.","criteria":["Есть конкретная ситуация вместо «всегда» и «постоянно»","Описано влияние без ярлыка личности","Предложены вопрос и выполнимое действие"],"question":"Что отличает наблюдение от ярлыка?","options":["Оно описывает конкретное поведение","Оно звучит громче","Оно содержит «ты всегда»"],"correct":0,"explanation":"Наблюдение можно обсуждать и проверять, не оценивая человека целиком.","minutes":20}]},{"title":"Договорённости и выступление","lessons":[{"id":"5","title":"Приоритеты и договорённости","theory":["Когда задач больше, чем времени, обещание «сделаю всё» увеличивает риск. Уточните обязательный результат, срок и зависимости. Предложите выбор: уменьшить объём, изменить срок или получить помощь.","Фиксируйте договорённость простым текстом: результат, ответственный, срок, проверка. Если появилась новая срочная задача, явно обсудите, какая из старых сдвинется. Граница — это информация о возможностях, а не конфликт."],"example":"«Сегодня до 18:00 могу подготовить выводы и таблицу. Полное оформление требует ещё двух часов. Что важнее: черновик сегодня или оформленная версия завтра к 12:00? После выбора подтвержу план письменно».","task":"Составьте ответ руководителю учебного проекта: на сегодня уже запланированы две задачи, добавилась третья срочная. Предложите два реалистичных варианта и зафиксируйте формат договорённости.","criteria":["Названы ограничение и влияние новой задачи","Даны два выполнимых варианта, а не просто отказ","Есть ответственный, результат и конкретный срок"],"question":"Что делать при конфликте сроков?","options":["Молча согласиться на всё","Согласовать объём, приоритет или новый срок","Исчезнуть до дедлайна"],"correct":1,"explanation":"Явное согласование помогает управлять ожиданиями и рисками.","minutes":20},{"id":"6","title":"Итог: готовность к знакомству и интервью","theory":["STAR помогает развернуть один пример: Situation — контекст, Task — задача, Action — ваши действия, Result — результат. Большая часть рассказа должна объяснять действие, а не долго описывать предысторию.","Соберите минутную презентацию и историю STAR в один пакет. Попросите собеседника пересказать, что он понял о вашем вкладе. Если пробы ещё не было, обозначьте её как план. Цель не заучить идеальную речь, а говорить понятно и честно."],"example":"S: команда не успевала к защите. T: согласовать минимальную версию. A: собрал обязательные части и распределил владельцев. R: показали рабочий прототип к сроку; анимацию перенесли. Вывод: раньше фиксировать приоритет.","task":"Отправьте самопрезентацию на 60 секунд, одну историю STAR и три вопроса будущей команде. Добавьте результат репетиции или конкретный план её проведения и один пункт развития.","criteria":["Презентация содержит аудиторию, пример и следующий шаг","STAR показывает личное действие и честный результат","Есть три содержательных вопроса и план улучшения после репетиции"],"question":"На чём сделать акцент в STAR?","options":["Только на должности","На длинной предыстории","На собственных действиях и результате"],"correct":2,"explanation":"История должна показывать, что именно вы сделали и к чему это привело.","minutes":40}]}]},{"id":"marketing","title":"Digital marketing basics","category":"Маркетинг","level":"С нуля","duration":"6 уроков · ~2,5 часа","color":"indigo","symbol":"↗","description":"От аудитории и предложения до контент-плана и измеримого эксперимента. Без рекламных расходов.","outcome":"Маркетинговый план учебного продукта: сегмент, предложение, контент и эксперимент с метриками.","skills":["Аудитория","Контент","Воронка"],"modules":[{"title":"Аудитория и предложение","lessons":[{"id":"1","title":"Сегмент и задача клиента","theory":["Аудитория — не просто возраст и пол. Полезный сегмент объединяет людей с похожей задачей и контекстом. Например, студенты, которые готовят первое портфолио к стажировке и не знают, как выбрать работы.","Сформулируйте потребность словами человека, а не названием функции. Отделите проверенные факты от гипотез. Короткие интервью или наблюдение помогают уточнить задачу, но несколько мнений не доказывают поведение всего рынка."],"example":"Широко: «Все, кто хочет учиться».\nТочнее: «Студенты перед первой стажировкой: за выходные собрать понятное портфолио без коммерческого опыта».\nГипотеза: основная трудность — отбор учебных работ.","task":"Выберите учебный продукт и один сегмент. Опишите ситуацию, задачу, препятствие и два вопроса для интервью без навязывания ответа.","criteria":["Сегмент задан через контекст, а не только демографию","Потребность отделена от функции продукта","Вопросы открытые, гипотезы не выданы за исследования"],"question":"Какой вопрос лучше для интервью?","options":["Вам ведь нужен наш курс?","Вы купите, если будет красиво?","Как вы решали эту задачу в последний раз?"],"correct":2,"explanation":"Вопрос о реальном поведении даёт больше информации, чем подталкивание к согласию.","minutes":20},{"id":"2","title":"Ценностное предложение","theory":["Предложение связывает аудиторию, результат, способ и ограничения. «Лучший курс на рынке» не объясняет пользу. «За три практики соберёте черновик портфолио из учебных работ» конкретнее, если продукт действительно это обеспечивает.","Не обещайте гарантированную работу, доход или результат, который зависит от внешних решений. Доказательством могут быть программа и образец задания. Отзывы и числа допустимы только подлинные; учебные примеры помечайте."],"example":"До: «Стань успешным быстро!»\nПосле: «Для студентов без коммерческих кейсов: за выходные отберите три учебные работы и оформите черновик портфолио по чек-листу. Трудоустройство не гарантируем».","task":"Напишите предложение своего учебного продукта: кому, какой результат, каким способом. Добавьте одно ограничение и реальный способ подтвердить обещание без выдуманных отзывов.","criteria":["Аудитория и результат названы конкретно","Способ достижения понятен и соответствует программе","Нет неподтверждённых гарантий, есть ограничение и доказательство"],"question":"Какое обещание корректнее?","options":["Гарантированная работа за два дня","Черновик портфолио по трём заданиям","Доход каждому без усилий"],"correct":1,"explanation":"Можно обещать обеспечиваемый продуктом результат, но не решения работодателей.","minutes":20}]},{"title":"Каналы и контент","lessons":[{"id":"3","title":"Воронка и выбор канала","theory":["Воронка описывает последовательность: заметил → заинтересовался → сделал пробное действие → получил ценность → вернулся. На каждом этапе нужен следующий шаг. Лайки сами по себе не доказывают обучение или покупку.","Выбирайте канал по месту и ситуации аудитории, а не по моде. Для учебного проекта достаточно гипотезы о двух бесплатных каналах и способа проверки. Не рассылайте сообщения без согласия и не используйте чужие контакты."],"example":"Студенческое сообщество → полезный разбор учебного кейса → страница с образцом задания → пробный урок → возвращение к практике.\nМетрика перехода: доля открывших пробный урок, а не число лайков.","task":"Постройте воронку из пяти шагов для своего продукта. Выберите два канала, объясните связь с сегментом и укажите одно измеримое действие на каждом этапе.","criteria":["Пять шагов ведут к ценности, а не обрываются на охвате","Два канала обоснованы поведением аудитории","Метрики действий и согласие на коммуникацию учтены"],"question":"Почему лайки не равны результату обучения?","options":["Потому что все лайки поддельные","Они не доказывают прохождение и применение урока","Их нельзя посчитать"],"correct":1,"explanation":"Это сигнал вовлечения в публикацию, а не подтверждение целевого действия.","minutes":20},{"id":"4","title":"Контент-план и призыв к действию","theory":["Каждая публикация должна отвечать на вопрос аудитории. Полезно чередовать объяснение, пример и самостоятельную практику. Один материал — одна основная мысль и один понятный следующий шаг.","Контент-план включает тему, задачу, формат, дату и метрику. Не называйте рекламу независимым мнением. Используйте собственные материалы или контент с подходящими правами. Призыв не должен давить страхом или ложной срочностью."],"example":"Тема: «Как выбрать учебную работу в портфолио».\nФормат: разбор одного примера.\nЗадача: снять страх отсутствия опыта.\nCTA: «Попробуйте отобрать один кейс по чек-листу».\nМетрика: переходы к заданию.","task":"Составьте контент-план из трёх публикаций: объяснение, пример, практика. Для каждой укажите вопрос сегмента, формат, CTA и метрику.","criteria":["Три темы связаны с реальными вопросами выбранного сегмента","У каждой публикации один ясный CTA","Метрики соответствуют цели, нет ложной срочности"],"question":"Какой CTA лучше для первого учебного знакомства?","options":["Срочно купи, иначе опоздаешь навсегда","Сделай всё сразу","Попробуйте одно бесплатное задание"],"correct":2,"explanation":"Небольшое понятное действие снижает неопределённость без давления.","minutes":20}]},{"title":"Измерение и план","lessons":[{"id":"5","title":"Метрики и бережный эксперимент","theory":["Для страницы полезна конверсия: целевые действия / визиты. Размеченные ссылки с UTM помогают отличать источники, но в метки нельзя помещать email или другие персональные данные. Сбор аналитики должен учитывать применимые правила и согласие.","Учебный эксперимент не требует покупки рекламы. Сравните два варианта заголовка в добровольном тесте понимания, заранее выбрав метрику. На маленькой группе результаты — наблюдения, а не доказанная статистическая победа."],"example":"Гипотеза: конкретный результат в заголовке будет понятнее общего лозунга.\nПроверка: показать варианты добровольцам, спросить «что вы получите?».\nМетрика: правильное понимание предложения.\nОграничение: малый удобный набор участников, не весь рынок.","task":"Спланируйте бесплатный тест двух заголовков. Укажите гипотезу, различие, способ набора добровольцев, метрику и правило решения. Приведите пример UTM без персональных данных.","criteria":["Меняется один фактор, метрика задана заранее","Участие добровольное, выводы учитывают малую выборку","UTM содержит источник/кампанию, но не личные данные"],"question":"Что нельзя помещать в публичные UTM-метки?","options":["Название канала","Email конкретного человека","Код учебной кампании"],"correct":1,"explanation":"Метки могут попасть в историю, логи и стороннюю аналитику; личные данные там недопустимы.","minutes":20},{"id":"6","title":"Итог: маркетинговый мини-план","theory":["План связывает сегмент и действие: кому помогаем, какое предложение показываем, где встречаемся, какой шаг предлагаем и как узнаём, что он понятен. Красивый контент без этой связи не заменяет стратегию.","Разделите факты, гипотезы и будущие тесты. Финальный результат курса — документ, а не запущенная реклама. Бюджет, доступ к кабинетам и публикация не нужны. Никогда не выдавайте учебные прогнозы за достигнутые продажи."],"example":"Пакет: один сегмент → предложение с ограничениями → два бесплатных канала → три публикации → один тест понимания → метрика и условие пересмотра. Все ещё не проверенные предположения отмечены.","task":"Соберите мини-план: сегмент, предложение, воронка, два канала, три публикации и эксперимент. Добавьте ограничения, метрику успеха и конкретное условие пересмотра. Не запускайте платную кампанию.","criteria":["Все части плана связаны с одной аудиторией и целью","Есть бесплатный проверяемый следующий шаг и метрика","Гипотезы, этические ограничения и условие пересмотра указаны"],"question":"Что считается результатом этого учебного проекта?","options":["Обещание гарантированных продаж","Покупка рекламы","Согласованный план с проверяемой гипотезой"],"correct":2,"explanation":"На этом этапе важен осмысленный и проверяемый план, а не расходы или выдуманная эффективность.","minutes":40}]}]},{"id":"earnings","title":"Основы заработка на digital-навыках","category":"Карьера","level":"Начальный","duration":"6 уроков · ~2,5 часа","color":"amber","symbol":"Go","description":"Превратите навык в понятную услугу: выберите задачу клиента, соберите учебный кейс и подготовьте безопасный первый отклик. Без обещаний лёгких денег.","outcome":"Пакет первой digital-услуги: описание, честный кейс, расчёт цены, бриф и персональный отклик.","skills":["Услуги","Портфолио","Работа с клиентом"],"modules":[{"title":"Навык и полезное предложение","lessons":[{"id":"1","title":"Какой результат вы можете предложить","theory":["Покупают не абстрактный навык, а полезный результат: очистить таблицу, сверстать страницу или подготовить макет. Начните с небольшой задачи, которую умеете выполнить и проверить самостоятельно. Не обещайте клиенту работу, которую за вас целиком должен сделать AI.","Выберите одну аудиторию и одно понятное ограничение объёма. Доход не гарантирован: он зависит от спроса, качества, поиска клиентов и договорённостей. Курс помогает подготовиться, но не обещает заказов или конкретной суммы."],"example":"Навык: таблицы. Услуга: привести до 300 строк учебного каталога к единому формату и выдать список спорных записей. Не включено: поиск новых данных, прогноз продаж и работа с чувствительными сведениями.","task":"Выберите один освоенный digital-навык и опишите небольшую услугу: кому, какой результат, какие входные данные, что входит и что не входит.","criteria":["Результат проверяем и связан с собственным навыком","Указаны аудитория, вход и границы объёма","Нет гарантий дохода или обещаний неподтверждённой компетенции"],"question":"Какое предложение конкретнее?","options":["Сделаю всё в digital","Приведу учебную таблицу до 300 строк к согласованному формату","Гарантирую рост дохода"],"correct":1,"explanation":"Небольшой определённый объём позволяет оценить срок, цену и качество результата.","minutes":20},{"id":"2","title":"Бриф: понять задачу до обещаний","theory":["До оценки спросите про цель, аудиторию, исходники, срок и критерии приёмки. Слова «быстро» и «красиво» требуют уточнения. Зафиксируйте допущения: если исходники не готовы, срок пока нельзя считать подтверждённым.","Получайте только необходимые данные и права доступа. Пароль владельца аккаунта не нужен для подготовки макета или текста. Используйте вымышленные данные в учебной работе и не публикуйте клиентские материалы без согласия."],"example":"Бриф: какой результат нужен? Кто его использует? Какие материалы готовы? Что считается принятым? Сколько раундов правок? Кто подтверждает? Какой срок реалистичен после получения исходников?","task":"Составьте бриф из семи вопросов для своей услуги. Добавьте два риска и условие, при котором нужно пересогласовать срок или объём.","criteria":["Вопросы уточняют цель, материалы и приёмку","Данные и доступы ограничены необходимым","Риски связаны с пересогласованием, а не скрыты"],"question":"Когда разумно подтвердить срок?","options":["До знакомства с задачей","После обещания максимально быстро","После уточнения объёма, исходников и зависимостей"],"correct":2,"explanation":"Срок зависит от реального объёма и доступных исходных данных.","minutes":20}]},{"title":"Кейс и экономика работы","lessons":[{"id":"3","title":"Честный кейс без коммерческого опыта","theory":["Учебный кейс подходит для начала, если он явно обозначен. Покажите задачу, ограничения, процесс, личный вклад и результат. Не выдавайте вымышленного заказчика за реального и не приписывайте себе чужие работы.","Кейс не обязан доказывать прибыль клиента. Достаточно показать качество: какие ошибки найдены в таблице, как проверена мобильная страница или почему выбранная иерархия помогает читать. Сохраняйте источники материалов и соблюдайте права."],"example":"Учебный кейс: вымышленный каталог из 100 строк. Нашёл 8 повторов по id, 3 пустых значения оставил для уточнения. Подготовил очищенную копию и журнал изменений. Реального заказчика и оплаченного результата не было.","task":"Оформите кейс выбранной услуги: задача, исходники, три шага работы, проверка и результат. Явно укажите учебный характер и свой вклад.","criteria":["Учебный кейс не маскируется под оплаченный заказ","Показаны действия и проверяемый результат","Указаны личный вклад и происхождение материалов"],"question":"Как честно представить первый кейс?","options":["Назвать учебным и показать процесс и проверку","Придумать клиента и отзыв","Скопировать чужой проект"],"correct":0,"explanation":"Честное обозначение учебного опыта сохраняет доверие и позволяет обсуждать реальные навыки.","minutes":20},{"id":"4","title":"Цена, время и границы правок","theory":["Цена должна учитывать выполнение, коммуникацию, проверку и правки. Учебный расчёт: плановые часы × выбранная ставка + прямые расходы. Это не универсальная рыночная цена: сравните объём и условия, не обещайте, что рынок примет расчёт.","Зафиксируйте результат, число включённых раундов правок и дополнительные работы. Условия оплаты, налоги и оформление зависят от вашей юрисдикции и статуса: проверяйте официальные требования и при необходимости обращайтесь к специалисту."],"example":"Учебный расчёт: 3 часа подготовки + 1 час обсуждения/правок = 4 часа. При условной ставке 500 ₽/час получается 2000 ₽. Это пример расчёта, не обещание заработка и не рекомендация рыночной цены.","task":"Рассчитайте учебную оценку услуги: часы по этапам, условная ставка, расходы, число правок. Укажите, что изменит цену и какие местные требования нужно проверить.","criteria":["Учтены обсуждение, проверка и правки","Цена названа учебной оценкой, не гарантией спроса","Есть границы дополнительных работ и проверка правил оформления"],"question":"Что нужно включать в оценку времени?","options":["Только непосредственное создание файла","Работу, общение, проверку и согласованные правки","Только поиск клиента"],"correct":1,"explanation":"Скрытая коммуникация и правки тоже занимают время и влияют на экономику задачи.","minutes":20}]},{"title":"Первый контакт и безопасный старт","lessons":[{"id":"5","title":"Персональный отклик и защита от обмана","theory":["Отклик показывает понимание задачи: кратко назовите потребность, релевантный кейс, предполагаемый результат и уточнение. Не отправляйте массовый спам и не собирайте чужие контакты без основания. Реальное обращение требует добровольного выбора человека — курс ничего не отправляет.","Не платите за обещание получить заказ, не сообщайте коды входа и не выполняйте большое бесплатное тестовое без понятной цели и границ. При подозрительных условиях остановитесь и проверьте площадку и договорённости. Это снижает риск, но не гарантирует безопасность любого клиента."],"example":"«Вижу, что вам нужен единый формат каталога. В учебном кейсе я проверял повторы и пропуски; могу показать журнал правок. Для оценки уточню количество строк и правила заполнения. Предлагаю сначала согласовать небольшой пример».","task":"Напишите персональный отклик на вымышленную задачу своей услуги. Добавьте три признака риска и безопасное действие при каждом. Никуда не отправляйте сообщение автоматически.","criteria":["Отклик связан с конкретной потребностью и честным кейсом","Есть уточнение вместо необоснованных гарантий","Риски включают предоплату за заказ, коды входа и чрезмерное бесплатное тестовое"],"question":"Что делать, если предлагают заплатить за доступ к гарантированному заказу?","options":["Немедленно заплатить","Передать код подтверждения","Остановиться и проверить условия; не платить за обещание"],"correct":2,"explanation":"Обещание гарантированного заказа за взнос — повод насторожиться, а не подтверждение надёжности.","minutes":20},{"id":"6","title":"Итог: пакет первой digital-услуги","theory":["Соберите предложение, бриф, кейс, оценку и отклик в единый пакет. Все части должны описывать одну задачу и соответствовать вашим реальным навыкам. Финальный результат курса — подготовка к самостоятельному поиску, не полученный заказ.","Следующий шаг — проверить понятность предложения у добровольного собеседника или изучить требования подходящей площадки. Не покупайте рекламу и не публикуйте личные данные ради завершения урока. Зафиксируйте, что хотите проверить и при каком результате пересмотрите услугу."],"example":"Пакет: очистка каталога → бриф → учебный кейс → оценка часов и правок → адресный черновик отклика → список рисков. Неизвестное: спрос, реальная цена, конкретный заказчик. Следующий шаг: добровольная проверка понятности.","task":"Отправьте пакет услуги: аудитория/результат, бриф, учебный кейс, оценка цены, черновик отклика и правила безопасности. Добавьте реалистичный следующий шаг без расходов и условие пересмотра предложения.","criteria":["Части связаны с одним реальным навыком и объёмом","Кейс честный, расчёт и условия прозрачны","Нет обещания дохода; есть риски и бесплатная проверка гипотезы"],"question":"Что является результатом курса?","options":["Подготовленная услуга и проверяемый следующий шаг, без гарантии дохода","Гарантированная зарплата","Обязательная покупка рекламы"],"correct":0,"explanation":"Курс даёт подготовленный пакет и навыки работы с задачей, а не обещает коммерческий успех.","minutes":40}]}]},{"id":"java","title":"Java за 21 день","category":"Разработка","level":"С нуля","duration":"21 день · 21 урок","color":"orange","symbol":"Jv","description":"Практический маршрут для начинающих: Java 17+, ООП, коллекции, файлы.","outcome":"Консольный менеджер задач с сохранением данных.","skills":["Java","ООП","Коллекции"],"modules":[{"title":"Базовый синтаксис","lessons":[{"id":"1","title":"Первая программа","minutes":20,"theory":["Java компилируется в байткод, который выполняет JVM. Метод main — точка входа; имя public class должно совпадать с именем файла.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"public class Main { public static void main(String[] args) { System.out.println(\"Hello, Java!\"); } }","task":"Создай Main.java, выведи своё имя и цель обучения. Запусти javac Main.java и java Main.","criteria":["Два сообщения выводятся","имя класса Main","программа компилируется"],"question":"Какой метод служит точкой входа?","options":["start","print","main"],"correct":2,"explanation":"main запускается JVM как точка входа."},{"id":"2","title":"Переменные и типы","minutes":20,"theory":["int хранит целые, double — дробные, boolean — true/false, String — текст. Java проверяет типы при компиляции.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"int count = 3; double price = 12.5; System.out.println(count * price); // 37.5","task":"Рассчитай цену 4 книг по 199.5 и выведи итог.","criteria":["Использованы int и double","итог вычислен","результат 798.0"],"question":"Какой тип подходит для дробной цены?","options":["String","double","boolean"],"correct":1,"explanation":"double представляет дробные числа."},{"id":"3","title":"Операторы и арифметика","minutes":20,"theory":["Операторы +, -, *, / и % выполняют арифметику. Деление двух int отбрасывает дробную часть; приведение к double сохраняет её.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"int a = 7, b = 2; System.out.println(a / b); // 3\nSystem.out.println((double)a / b); // 3.5","task":"Раздели 17 конфет между 4 людьми, выведи количество на человека и остаток.","criteria":["Целое деление","оператор %","результаты 4 и 1"],"question":"Чему равно 17 % 4?","options":["0","4","1"],"correct":2,"explanation":"Остаток равен единице."},{"id":"4","title":"Ввод и строки","minutes":20,"theory":["Scanner читает данные из System.in. nextInt читает целое число, nextLine — строку; после nextInt может остаться перевод строки.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"java.util.Scanner sc = new java.util.Scanner(System.in);\nString name = sc.nextLine();\nSystem.out.println(\"Привет, \" + name);","task":"Запроси имя и возраст отдельными строками, выведи приветствие.","criteria":["Использован Scanner","ввод обрабатывается","вывод содержит имя"],"question":"Как прочитать целую строку?","options":["length()","nextInt()","nextLine()"],"correct":2,"explanation":"nextLine читает строку до перевода строки."},{"id":"5","title":"Условия if и else","minutes":20,"theory":["if выполняет блок при истинном условии, else — иначе. Сравнение чисел делается через ==, строк по содержимому — equals.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"int score = 82; if (score >= 60) { System.out.println(\"Зачёт\"); } else { System.out.println(\"Повтори\"); }","task":"Проверь температуру: ниже 0 — мороз, иначе — не мороз. Проверь 0 и -1.","criteria":["Есть две ветви","граница 0 верна","два теста"],"question":"Как сравнить содержимое двух String?","options":["equals()","==","length()"],"correct":0,"explanation":"equals сравнивает содержимое строк."},{"id":"6","title":"Циклы for и while","minutes":20,"theory":["for подходит для известного числа повторений, while — когда продолжение зависит от условия. Следи, чтобы условие могло стать ложным.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"for (int i = 1; i <= 5; i++) { System.out.println(i); }","task":"Вычисли сумму чисел от 1 до 10 циклом.","criteria":["Цикл заканчивается","сумма накапливается","результат 55"],"question":"Сколько раз выполнится for (int i=0; i<3; i++)?","options":["3","2","4"],"correct":0,"explanation":"Индексы 0, 1, 2 дают три итерации."},{"id":"7","title":"Массивы","minutes":20,"theory":["Массив имеет фиксированную длину и хранит элементы одного типа. Индексация начинается с нуля; length — поле длины.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"int[] scores = {10, 20, 30};\nSystem.out.println(scores[0]); // 10","task":"Найди максимальное число в массиве {4,9,2,7} циклом.","criteria":["Есть массив","максимум вычислен сравнением","ответ 9"],"question":"Какой индекс первого элемента?","options":["1","0","-1"],"correct":1,"explanation":"Первый элемент имеет индекс 0."}]},{"title":"Объекты и коллекции","lessons":[{"id":"8","title":"Методы","minutes":25,"theory":["Методы выделяют повторяемую логику. Параметры принимают значения, return возвращает результат; void означает отсутствие возвращаемого значения.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"static int square(int x) { return x * x; }\n// В main: System.out.println(square(5));","task":"Напиши метод area(int w, int h), возвращающий площадь прямоугольника. Проверь 3 и 4.","criteria":["Метод возвращает int","использует параметры","ответ 12"],"question":"Что значит void?","options":["Метод скрыт","Метод не возвращает значение","Метод возвращает число"],"correct":1,"explanation":"void обозначает отсутствие результата."},{"id":"9","title":"String и StringBuilder","minutes":25,"theory":["String неизменяем; операции создают новые строки. StringBuilder удобен для многократного добавления текста.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"StringBuilder b = new StringBuilder();\nb.append(\"Skill\").append(\"Twin\");\nSystem.out.println(b.toString());","task":"Собери строку из трёх названий через StringBuilder и выведи её.","criteria":["Использован append","три названия","результат выведен"],"question":"Какой тип удобен для многократного append?","options":["int","boolean","StringBuilder"],"correct":2,"explanation":"StringBuilder изменяем и предназначен для сборки текста."},{"id":"10","title":"Классы и объекты","minutes":25,"theory":["Класс описывает поля и методы, объект — конкретный экземпляр. new создаёт экземпляр.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"class Book { String title; Book(String title) { this.title = title; } }\n// В main: Book b = new Book(\"Java\");","task":"Создай класс Student с именем и методом приветствия. Создай два объекта.","criteria":["Класс и конструктор","разные имена","вызов метода"],"question":"Что делает new Book(...)?","options":["Удаляет класс","Печатает объект","Создаёт экземпляр"],"correct":2,"explanation":"new создаёт объект и вызывает конструктор."},{"id":"11","title":"Инкапсуляция","minutes":25,"theory":["private ограничивает прямой доступ к полю. Методы позволяют проверять данные и сохранять корректность объекта.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"class Wallet { private int balance; void add(int n) { if (n > 0) balance += n; } int getBalance() { return balance; } }","task":"Добавь в Wallet метод spend, не позволяющий уйти в минус.","criteria":["Поле private","проверка остатка","тест недостатка средств"],"question":"Что означает private?","options":["Доступ ограничен классом","Доступен всем","Поле неизменяемо"],"correct":0,"explanation":"private скрывает член от внешнего прямого доступа."},{"id":"12","title":"Наследование и интерфейсы","minutes":25,"theory":["extends связывает класс с родителем; implements объявляет реализацию интерфейса. Интерфейс задаёт контракт поведения.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"interface Payable { int total(); }\nclass Ticket implements Payable { public int total() { return 100; } }","task":"Реализуй интерфейс Shape с методом area() в двух классах.","criteria":["Интерфейс","две реализации","вызовы area"],"question":"Как класс реализует интерфейс?","options":["extends","import","implements"],"correct":2,"explanation":"implements используется для интерфейсов."},{"id":"13","title":"ArrayList","minutes":25,"theory":["ArrayList — изменяемый список. add добавляет, get читает по индексу, size возвращает размер. Для чисел используют Integer.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"java.util.ArrayList<String> names = new java.util.ArrayList<>();\nnames.add(\"Анна\"); names.add(\"Иван\");\nSystem.out.println(names.size());","task":"Создай список из трёх задач, удали вторую по индексу и выведи остаток.","criteria":["Три добавления","remove(1)","два элемента"],"question":"Как узнать размер ArrayList?","options":["length","size()","count()"],"correct":1,"explanation":"Метод size возвращает количество элементов."},{"id":"14","title":"HashMap","minutes":25,"theory":["Map связывает ключ со значением. HashMap позволяет быстро искать значение по ключу; одинаковый ключ заменяет старое значение.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"java.util.Map<String,Integer> points = new java.util.HashMap<>();\npoints.put(\"Анна\", 12); System.out.println(points.get(\"Анна\"));","task":"Создай словарь цен трёх товаров и выведи цену одного по ключу.","criteria":["Есть три пары","поиск по ключу","верный вывод"],"question":"Что делает put для существующего ключа?","options":["Удаляет карту","Создаёт второй одинаковый ключ","Заменяет значение"],"correct":2,"explanation":"Ключи уникальны; put обновляет значение."}]},{"title":"Практический проект","lessons":[{"id":"15","title":"Исключения","minutes":25,"theory":["try/catch позволяет обработать исключение. Перехватывай ожидаемый тип, не скрывай ошибки молча.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"try { int n = Integer.parseInt(\"abc\"); } catch (NumberFormatException e) { System.out.println(\"Введите число\"); }","task":"Обработай неверный ввод числа и выведи понятное сообщение. Проверь 42 и abc.","criteria":["parseInt","конкретный catch","оба теста"],"question":"Что выбросит Integer.parseInt(\"abc\")?","options":["IOException","Ничего","NumberFormatException"],"correct":2,"explanation":"Строка не является целым числом."},{"id":"16","title":"Работа с файлами","minutes":25,"theory":["Files.readString и Files.writeString работают с текстовыми файлами (Java 11+). Операции ввода-вывода могут вызвать IOException.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"java.nio.file.Path p = java.nio.file.Path.of(\"notes.txt\");\njava.nio.file.Files.writeString(p, \"Привет\");\nSystem.out.println(java.nio.file.Files.readString(p)); // main throws java.io.IOException","task":"Запиши три задачи в notes.txt, прочитай и выведи их. Обработай IOException или объяви throws.","criteria":["Запись","чтение","обработка исключения"],"question":"Какой метод читает текст файла целиком?","options":["println","parseInt","Files.readString"],"correct":2,"explanation":"readString читает файл в строку."},{"id":"17","title":"Лямбды и Stream","minutes":25,"theory":["Лямбда задаёт короткую функцию; stream().filter выбирает элементы, map преобразует. toList завершает поток (Java 16+).","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"var xs = java.util.List.of(1,2,3,4);\nSystem.out.println(xs.stream().filter(n -> n % 2 == 0).toList());","task":"Из списка чисел выбери положительные и удвой их через map.","criteria":["filter","map","результат проверен"],"question":"Какой оператор оставляет только подходящие элементы?","options":["filter","map","println"],"correct":0,"explanation":"filter проверяет условие каждого элемента."},{"id":"18","title":"Тестирование методов","minutes":25,"theory":["Проверяй обычный случай, границы и ошибки. Простые проверки можно сделать через if и AssertionError; затем изучать JUnit.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"if (square(3) != 9) throw new AssertionError(\"square\");\nif (square(0) != 0) throw new AssertionError(\"zero\");","task":"Напиши метод max двух int и три проверки: порядок, равенство, отрицательные.","criteria":["Три теста","ожидаемые значения","метод проверяется"],"question":"Что проверяет граничный тест?","options":["Крайний случай входа","Имя компьютера","Цвет редактора"],"correct":0,"explanation":"Граница выявляет ошибки на краях допустимых данных."},{"id":"19","title":"Проект: модель задач","minutes":35,"theory":["Раздели сущности и логику: Task хранит название и статус, TaskService управляет списком. Начни с маленьких методов.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"class Task { String title; boolean done; Task(String title) { this.title = title; } }","task":"Создай Task и сервис с add и list; добавь три задачи.","criteria":["Модель","список","метод добавления"],"question":"Куда лучше поместить управление списком?","options":["В случайный комментарий","В сервис задач","В имя задачи"],"correct":1,"explanation":"Сервис отвечает за операции над коллекцией."},{"id":"20","title":"Проект: команды и сохранение","minutes":35,"theory":["Консольный интерфейс читает команды, проверяет ввод и вызывает сервис. Для сохранения можно использовать простой текстовый формат с отдельной строкой на задачу.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"String command = \"list\";\nswitch (command) { case \"list\" -> System.out.println(\"Список\"); case \"exit\" -> System.out.println(\"Выход\"); default -> System.out.println(\"Неизвестная команда\"); }","task":"Добавь команды add/list/done/exit и сохранение в файл. Проверь перезапуск.","criteria":["Четыре команды","запись и чтение","проверка неверного ввода"],"question":"Зачем ветка default в switch?","options":["Для создания класса","Для неизвестных команд","Для ускорения диска"],"correct":1,"explanation":"default обрабатывает непредусмотренные значения."},{"id":"21","title":"Финал: Java Task Manager","minutes":35,"theory":["Собери проект: модель, сервис, ввод, хранение и проверки. Документируй запуск и известные ограничения. За 21 день цель — основы, не профессиональное владение Java.","Пример — фрагмент Java 17+: инструкции помещай в main, объявления методов и классов — в соответствующие классы. Проверяй код в JDK."],"example":"// Main.java — точка входа\n// Task.java — модель\n// TaskService.java — операции\n// javac *.java && java Main","task":"Подготовь рабочий менеджер задач, README и демонстрацию трёх сценариев: добавление, завершение, повторный запуск.","criteria":["Проект компилируется","данные сохраняются","README и три сценария"],"question":"Что лучше подтверждает готовность проекта?","options":["Только число строк","Запуск и проверенные сценарии","Красивое имя"],"correct":1,"explanation":"Рабочая демонстрация и тесты подтверждают функциональность."}]}]},{"id":"javascript","title":"JavaScript за 21 день","category":"Разработка","level":"С нуля","duration":"21 день · 21 урок","color":"yellow","symbol":"JS","description":"Практический маршрут для начинающих: JavaScript, DOM, события, асинхронность.","outcome":"Интерактивный веб-менеджер задач с сохранением в браузере.","skills":["JavaScript","DOM","Web API"],"modules":[{"title":"Основы языка","lessons":[{"id":"1","title":"Первая программа","minutes":20,"theory":["JavaScript выполняется в браузере или Node.js. console.log выводит значения в консоль; инструкции можно выполнять по очереди.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"console.log(\"Hello, JavaScript!\");","task":"Выведи имя и цель обучения в консоли браузера или Node.js.","criteria":["Два сообщения","корректный синтаксис","результат проверен"],"question":"Что выводит сообщение в консоль?","options":["printLine","console.log","alertText"],"correct":1,"explanation":"console.log выводит сообщение в консоль."},{"id":"2","title":"let, const и типы","minutes":20,"theory":["let позволяет менять привязку, const — нет. Базовые типы включают number, string, boolean, undefined и null.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const price = 120; let count = 3; count += 1; console.log(price * count); // 480","task":"Рассчитай стоимость 5 товаров, используя const для цены и let для количества.","criteria":["Оба объявления","вычисление","вывод"],"question":"Как объявить переменную с неизменяемой привязкой?","options":["var","let","const"],"correct":2,"explanation":"const запрещает повторное присваивание привязки."},{"id":"3","title":"Операторы и преобразования","minutes":20,"theory":["+ складывает числа или соединяет строки. Number преобразует числовой текст. === сравнивает без неявного преобразования типов.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"console.log(Number(\"10\") + 5); // 15\nconsole.log(10 === \"10\"); // false","task":"Преобразуй строки \"24\" и \"6\" в числа, выведи сумму и частное.","criteria":["Number","сумма 30","частное 4"],"question":"Чему равно 10 === \"10\"?","options":["true","undefined","false"],"correct":2,"explanation":"Типы различаются, строгое равенство ложно."},{"id":"4","title":"Условия","minutes":20,"theory":["if/else выбирает ветвь по условию. Используй строгие сравнения и учитывай граничные значения.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const age = 18; if (age >= 18) { console.log(\"OK\"); } else { console.log(\"Нет\"); }","task":"Напиши проверку оценки: от 60 зачёт, иначе повтор. Проверь 59 и 60.","criteria":["Две ветви","верная граница","два теста"],"question":"Когда выполняется else?","options":["Когда if ложно","Всегда","Когда if истинно"],"correct":0,"explanation":"else выполняется при ложном условии if."},{"id":"5","title":"Циклы","minutes":20,"theory":["for повторяет действия с счётчиком, while — пока условие истинно. for...of перебирает значения коллекции.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"let sum = 0; for (let i = 1; i <= 5; i++) { sum += i; } console.log(sum); // 15","task":"Сложи числа от 1 до 10 циклом.","criteria":["Счётчик","накопление суммы","55"],"question":"Сколько итераций в for(let i=0;i<4;i++)?","options":["5","4","3"],"correct":1,"explanation":"Значения i от 0 до 3."},{"id":"6","title":"Массивы","minutes":20,"theory":["Массив — упорядоченная коллекция. Индекс начинается с нуля; push добавляет, length показывает размер.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const tasks = [\"читать\", \"писать\"]; tasks.push(\"учиться\"); console.log(tasks[2]);","task":"Создай список из трёх дел, добавь ещё одно и выведи последнее.","criteria":["Массив","push","последний элемент"],"question":"Что возвращает [10,20][0]?","options":["undefined","20","10"],"correct":2,"explanation":"Первый элемент имеет индекс 0."},{"id":"7","title":"Функции","minutes":20,"theory":["Функция принимает параметры и возвращает результат через return. Стрелочная функция подходит для компактной записи.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const square = x => x * x; console.log(square(6)); // 36","task":"Напиши функцию discount(price, percent), возвращающую цену после скидки.","criteria":["Два параметра","формула","проверка 100 и 20 даёт 80"],"question":"Что делает return?","options":["Возвращает значение","Повторяет цикл","Печатает строку"],"correct":0,"explanation":"return завершает вызов и возвращает результат."}]},{"title":"Интерактивный браузер","lessons":[{"id":"8","title":"Объекты","minutes":25,"theory":["Объект хранит свойства как пары ключ–значение. Свойства доступны через точку или квадратные скобки.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const user = {name: \"Анна\", points: 20}; user.points += 10; console.log(user.points);","task":"Создай объект книги с названием, автором и статусом чтения.","criteria":["Три свойства","изменение статуса","вывод"],"question":"Как прочитать свойство name объекта user?","options":["user( name )","user.name","user->name"],"correct":1,"explanation":"Точка обращается к свойству объекта."},{"id":"9","title":"map, filter, reduce","minutes":25,"theory":["map преобразует каждый элемент, filter отбирает по условию, reduce объединяет значения в один результат.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const nums = [1,2,3,4];\nconsole.log(nums.filter(n => n % 2 === 0).map(n => n * 2)); // [4,8]","task":"Из списка цен выбери цены выше 100 и посчитай сумму через reduce с начальным 0.","criteria":["filter","reduce","проверка результата"],"question":"Какой метод возвращает отобранные элементы?","options":["filter","push","map"],"correct":0,"explanation":"filter оставляет элементы, удовлетворяющие предикату."},{"id":"10","title":"Строки и шаблоны","minutes":25,"theory":["Шаблонные строки в обратных кавычках подставляют выражения через ${}. trim убирает пробелы по краям, includes проверяет подстроку.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const name = \" Анна \".trim(); console.log(`Привет, ${name}!`);","task":"Нормализуй имя пользователя и выведи приветствие шаблонной строкой.","criteria":["trim","шаблон","ожидаемый вывод"],"question":"Что делает trim()?","options":["Меняет регистр","Удаляет пробелы по краям","Удаляет все буквы"],"correct":1,"explanation":"trim убирает начальные и конечные пробельные символы."},{"id":"11","title":"DOM: поиск элементов","minutes":25,"theory":["DOM — дерево HTML-элементов. querySelector ищет первый элемент по CSS-селектору; textContent безопасно задаёт обычный текст.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"// HTML: <h1 id=\"title\">Старый текст</h1>\ndocument.querySelector(\"#title\").textContent = \"SkillTwin\";","task":"Создай HTML с заголовком и абзацем, измени оба через querySelector.","criteria":["Два элемента","правильные селекторы","текст изменён"],"question":"Какой селектор ищет id title?","options":["title","#title",".title"],"correct":1,"explanation":"Символ # означает поиск по id."},{"id":"12","title":"События и кнопки","minutes":25,"theory":["addEventListener связывает действие пользователя с функцией. Для кнопки обычно используется событие click.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"// HTML: <button id=\"btn\">Нажми</button>\ndocument.querySelector(\"#btn\").addEventListener(\"click\", () => console.log(\"Клик\"));","task":"Сделай счётчик кликов: кнопка увеличивает число в span.","criteria":["Обработчик click","переменная счётчика","обновление текста"],"question":"Как называется событие нажатия кнопки?","options":["click","loadText","submitForm"],"correct":0,"explanation":"click возникает при активации кнопки."},{"id":"13","title":"Формы и валидация","minutes":25,"theory":["При submit можно вызвать preventDefault, чтобы не перезагружать страницу. Проверяй данные и выводи текст через textContent.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"// HTML: <form id=\"f\"><input id=\"name\"><button>OK</button></form>\ndocument.querySelector(\"#f\").addEventListener(\"submit\", e => { e.preventDefault(); console.log(document.querySelector(\"#name\").value.trim()); });","task":"Создай форму добавления задачи: пустое название отклоняется, корректное выводится.","criteria":["submit","trim и проверка","сообщение без перезагрузки"],"question":"Что предотвращает обычную отправку формы?","options":["remove()","stopText","preventDefault()"],"correct":2,"explanation":"preventDefault отменяет стандартное действие события."},{"id":"14","title":"Создание элементов DOM","minutes":25,"theory":["createElement создаёт узел, append добавляет его в дерево. Для пользовательского текста используй textContent, а не innerHTML.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const li = document.createElement(\"li\"); li.textContent = \"Выучить JS\"; document.querySelector(\"ul\").append(li);","task":"Добавляй задачи из поля ввода в список li. Не вставляй ввод как HTML.","criteria":["createElement","textContent","append"],"question":"Как безопасно вставить пользовательский текст?","options":["textContent","eval","innerHTML"],"correct":0,"explanation":"textContent вставляет текст без интерпретации HTML."}]},{"title":"Асинхронность и проект","lessons":[{"id":"15","title":"JSON и localStorage","minutes":25,"theory":["JSON.stringify превращает данные в строку, JSON.parse восстанавливает объект. localStorage хранит строки в браузере; не используй его для паролей.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"localStorage.setItem(\"tasks\", JSON.stringify([\"JavaScript\"]));\nconsole.log(JSON.parse(localStorage.getItem(\"tasks\")));","task":"Сохрани список задач и восстанови его после перезагрузки. Обработай отсутствие данных.","criteria":["Сериализация","восстановление","проверка перезагрузки"],"question":"Что хранит localStorage?","options":["Функции напрямую","Строки","DOM-узлы напрямую"],"correct":1,"explanation":"Данные localStorage хранятся строками."},{"id":"16","title":"Promise и async/await","minutes":25,"theory":["Promise представляет будущий результат. await ждёт завершения Promise внутри async-функции; ошибки можно ловить try/catch.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"async function run() { const n = await Promise.resolve(42); console.log(n); } run();","task":"Создай Promise, который возвращает текст, и выведи его внутри async-функции.","criteria":["Promise","await","вывод результата"],"question":"Где обычно используется await?","options":["В CSS","В комментарии","В async-функции"],"correct":2,"explanation":"await допустим в async-функции и на верхнем уровне модуля."},{"id":"17","title":"Fetch и обработка ошибок","minutes":25,"theory":["fetch делает HTTP-запрос. HTTP 404 не обязательно отклоняет Promise, поэтому проверяй response.ok перед чтением JSON.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"async function load() { const r = await fetch(\"./data.json\"); if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); }\nload().then(console.log).catch(console.error);","task":"Создай data.json и загрузи его через локальный HTTP-сервер. Проверь отсутствующий файл.","criteria":["fetch","response.ok","обработка ошибки"],"question":"Что проверить после fetch перед чтением JSON?","options":["response.ok","Имя функции","Размер экрана"],"correct":0,"explanation":"response.ok показывает успешный HTTP-статус."},{"id":"18","title":"Модули и структура проекта","minutes":25,"theory":["export делает функцию доступной другим модулям, import подключает её. В браузере используй script type=\"module\" и HTTP-сервер.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"// math.js\nexport const add = (a,b) => a+b;\n// app.js\nimport {add} from \"./math.js\"; console.log(add(2,3));","task":"Вынеси функции работы с задачами в tasks.js и импортируй в app.js.","criteria":["Два файла","export/import","рабочий вызов"],"question":"Как подключить именованный экспорт add?","options":["include add","require HTML","import {add} from \"./math.js\""],"correct":2,"explanation":"Именованный экспорт импортируется в фигурных скобках."},{"id":"19","title":"Отладка и тесты","minutes":35,"theory":["Используй DevTools, точки останова и console.assert. Проверяй пустой ввод, обычные данные и граничные случаи.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const total = xs => xs.reduce((s,x) => s+x,0);\nconsole.assert(total([]) === 0); console.assert(total([2,3]) === 5);","task":"Напиши функцию подсчёта завершённых задач и три проверки.","criteria":["Пустой список","смешанный список","все завершены"],"question":"Зачем нужен breakpoint?","options":["Удалить файл","Остановить выполнение для анализа","Сохранить пароль"],"correct":1,"explanation":"Точка останова позволяет изучить состояние программы."},{"id":"20","title":"Проект: интерфейс задач","minutes":35,"theory":["Соедини модель данных, форму и функцию render. При изменении списка перерисуй его; не дублируй обработчики при каждом рендере.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"const tasks = [];\nfunction addTask(title) { tasks.push({title, done:false}); }\naddTask(\"Учить JS\");","task":"Собери интерфейс задач с добавлением, отметкой выполнения и удалением.","criteria":["Три операции","отображение состояния","обработка пустого ввода"],"question":"Когда вызывать render после изменения данных?","options":["Никогда","После изменения","До изменения только"],"correct":1,"explanation":"Рендер обновляет экран согласно новому состоянию."},{"id":"21","title":"Финал: JavaScript Task App","minutes":35,"theory":["Сохрани задачи в localStorage, проверь перезагрузку, мобильное отображение и ошибки. Подготовь README с запуском. 21 день — вводный практический маршрут.","Пример запускай в консоли браузера или Node.js; для DOM и localStorage нужна веб-страница. На платформе код не исполняется."],"example":"// index.html + app.js + style.css\n// Сценарий: добавить → завершить → перезагрузить\n// Проверить сохранённый статус задачи","task":"Заверши приложение задач и проверь добавление, удаление, завершение и восстановление после перезагрузки.","criteria":["Четыре операции работают","мобильный экран","инструкция запуска"],"question":"Что подтверждает сохранение данных?","options":["Длина файла","Цвет кнопки","Задачи после перезагрузки"],"correct":2,"explanation":"Восстановление после перезагрузки демонстрирует сохранение."}]}]},{"id":"cpp","title":"C++ за 21 день","category":"Разработка","level":"С нуля","duration":"21 день · 21 урок","color":"blue","symbol":"C++","description":"Практический маршрут для начинающих: C++17, STL, функции, классы, файлы.","outcome":"Консольный менеджер задач с использованием STL.","skills":["C++","STL","ООП"],"modules":[{"title":"Базовые конструкции","lessons":[{"id":"1","title":"Первая программа","minutes":20,"theory":["C++ компилируется в исполняемый файл. main — точка входа, iostream предоставляет std::cout. Для курса используй стандарт C++17.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"#include <iostream>\nint main() { std::cout << \"Hello, C++!\\n\"; return 0; }","task":"Создай main.cpp, выведи имя и цель. Собери g++ -std=c++17 main.cpp -o app и запусти.","criteria":["Есть main","программа компилируется","два сообщения"],"question":"Какая функция — точка входа?","options":["cout","include","main"],"correct":2,"explanation":"main запускает программу."},{"id":"2","title":"Типы и переменные","minutes":20,"theory":["int хранит целые, double — дробные, bool — логические значения. std::string хранит текст; подключи <string>.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"int count = 3; double price = 25.5; std::cout << count * price; // 76.5","task":"Рассчитай стоимость 4 товаров по 19.5, выведи сумму.","criteria":["int и double","вычисление","78"],"question":"Какой тип подходит для дробного значения?","options":["int","bool","double"],"correct":2,"explanation":"double хранит числа с дробной частью."},{"id":"3","title":"Ввод и арифметика","minutes":20,"theory":["std::cin читает значения, std::cout выводит. Деление int отбрасывает дробную часть; % даёт остаток.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"int a, b; std::cin >> a >> b; if (b != 0) std::cout << a / b << \" \" << a % b;","task":"Введи число конфет и людей, выведи целое частное и остаток. Обработай ноль.","criteria":["Ввод","защита от нуля","остаток"],"question":"Что делает % для целых?","options":["Делит с дробью","Находит остаток","Умножает"],"correct":1,"explanation":"% возвращает остаток от целочисленного деления."},{"id":"4","title":"Условия","minutes":20,"theory":["if/else выбирает ветку. == сравнивает, = присваивает. Используй фигурные скобки для ясности.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"int score = 70; if (score >= 60) { std::cout << \"OK\"; } else { std::cout << \"Retry\"; }","task":"Проверь число: положительное, отрицательное или ноль.","criteria":["Три ветви","тесты -1,0,1","правильные сообщения"],"question":"Какой оператор сравнивает равенство?","options":["==","+=","="],"correct":0,"explanation":"== сравнивает значения."},{"id":"5","title":"Циклы","minutes":20,"theory":["for удобен для счётчика, while — для условия. Не забудь изменить счётчик; избегай выхода за границы коллекции.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"int sum = 0; for (int i=1; i<=5; ++i) sum += i; std::cout << sum;","task":"Посчитай сумму от 1 до 10 циклом.","criteria":["Счётчик","накопление","55"],"question":"Сколько раз выполнится for(int i=0;i<3;++i)?","options":["2","3","4"],"correct":1,"explanation":"Три итерации: 0, 1, 2."},{"id":"6","title":"Функции","minutes":20,"theory":["Функция имеет тип результата, имя и параметры. return возвращает значение; void обозначает отсутствие результата.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"int square(int x) { return x*x; }\n// В main: std::cout << square(4);","task":"Напиши функцию max2(int a, int b) и проверь два порядка аргументов и равенство.","criteria":["Тип результата int","два параметра","три теста"],"question":"Что означает void?","options":["Нет возвращаемого значения","Текст","Целое число"],"correct":0,"explanation":"void обозначает отсутствие возвращаемого значения."},{"id":"7","title":"std::vector","minutes":20,"theory":["vector — динамический массив из <vector>. push_back добавляет элементы, size возвращает размер; at проверяет границы.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"std::vector<int> v{3,1,4}; v.push_back(9); std::cout << v.at(0);","task":"Найди максимум в vector из пяти чисел, не задавая максимум равным нулю.","criteria":["vector","начальное значение из массива","проверка отрицательных"],"question":"Как добавить элемент в конец vector?","options":["insert_end","appendText","push_back"],"correct":2,"explanation":"push_back добавляет элемент в конец."}]},{"title":"Типы и управление ресурсами","lessons":[{"id":"8","title":"std::string","minutes":25,"theory":["std::string поддерживает size, find, substr и объединение через +. getline читает строку целиком.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"std::string s = \"SkillTwin\"; std::cout << s.substr(0,5); // Skill","task":"Прочитай строку через getline, выведи длину и первые три символа, если они есть.","criteria":["getline","проверка длины","substr"],"question":"Что возвращает substr(0,3)?","options":["Первые три символа, если доступны","Последние три символа","Размер строки"],"correct":0,"explanation":"substr извлекает подстроку с указанной позиции."},{"id":"9","title":"Ссылки и const","minutes":25,"theory":["Ссылка T& обращается к существующему объекту; const T& позволяет передать объект без копии и не менять его через ссылку.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"void increment(int& x) { ++x; }\n// В main: int n=5; increment(n); // n=6","task":"Напиши функцию, которая увеличивает число через ссылку, и функцию чтения vector через const&.","criteria":["Обе сигнатуры","изменение числа","чтение без изменения"],"question":"Что делает int& параметр?","options":["Создаёт файл","Позволяет изменить исходное число","Всегда копирует число"],"correct":1,"explanation":"Неконстантная ссылка обращается к исходному объекту."},{"id":"10","title":"Указатели и nullptr","minutes":25,"theory":["Указатель хранит адрес объекта, & получает адрес, * разыменовывает. Никогда не разыменовывай nullptr или висячий указатель.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"int x=7; int* p=&x; if(p != nullptr) std::cout << *p;","task":"Создай указатель на локальное число, измени число через *p и проверь nullptr отдельно.","criteria":["Адрес через &","безопасное разыменование","проверка nullptr"],"question":"Что нужно сделать перед разыменованием потенциально пустого указателя?","options":["Увеличить адрес","Удалить переменную","Проверить nullptr"],"correct":2,"explanation":"Пустой указатель нельзя разыменовывать; также следи за временем жизни."},{"id":"11","title":"struct и class","minutes":25,"theory":["struct и class объединяют данные и методы. В struct доступ по умолчанию public, в class — private.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"struct Task { std::string title; bool done=false; };\n// В main: Task t{\"Учить C++\"};","task":"Создай struct Book с названием и статусом, создай два экземпляра.","criteria":["Два поля","два объекта","вывод"],"question":"Какой доступ по умолчанию у class?","options":["public","protected","private"],"correct":2,"explanation":"У class члены по умолчанию private."},{"id":"12","title":"Конструкторы и инкапсуляция","minutes":25,"theory":["Конструктор инициализирует объект, список инициализации задаёт поля до тела конструктора. private защищает состояние.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"class Wallet { int balance; public: explicit Wallet(int b): balance(b) {} int get() const { return balance; } };","task":"Создай класс Counter с начальным значением, increment и get.","criteria":["private поле","конструктор","два метода"],"question":"Когда вызывается конструктор?","options":["При создании объекта","При каждом cout","При закрытии файла"],"correct":0,"explanation":"Конструктор инициализирует объект при создании."},{"id":"13","title":"RAII и умные указатели","minutes":25,"theory":["RAII связывает ресурс с временем жизни объекта. std::unique_ptr владеет объектом единолично и освобождает его при уничтожении; подключи <memory>.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"auto p = std::make_unique<int>(42); std::cout << *p;","task":"Создай unique_ptr для числа и объясни, когда освобождается память. Не используй ручной delete.","criteria":["make_unique","корректное чтение","объяснение времени жизни"],"question":"Кто освобождает объект unique_ptr?","options":["Деструктор владельца","cout","Компилятор при чтении строки"],"correct":0,"explanation":"unique_ptr освобождает принадлежащий ресурс при уничтожении."},{"id":"14","title":"std::map","minutes":25,"theory":["map хранит пары ключ–значение с уникальными ключами в упорядоченном виде. find позволяет проверить наличие без вставки.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"std::map<std::string,int> m{{\"Анна\",10}}; m[\"Иван\"]=20; auto it=m.find(\"Анна\"); if(it!=m.end()) std::cout<<it->second;","task":"Создай словарь цен, найди существующий и отсутствующий товар через find.","criteria":["Три пары","find","проверка end"],"question":"Что возвращает find при отсутствии ключа?","options":["0","end()","nullptr"],"correct":1,"explanation":"find возвращает итератор end при отсутствии элемента."}]},{"title":"Алгоритмы и проект","lessons":[{"id":"15","title":"Алгоритмы STL","minutes":25,"theory":["<algorithm> содержит sort, find и другие алгоритмы. begin/end задают диапазон; sort по умолчанию сортирует по возрастанию.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"std::vector<int> v{3,1,2}; std::sort(v.begin(),v.end()); // 1,2,3","task":"Отсортируй vector и проверь наличие числа через std::find.","criteria":["sort","find","проверка end"],"question":"Что делает std::sort по умолчанию для int?","options":["Удаляет числа","Считает сумму","Сортирует по возрастанию"],"correct":2,"explanation":"Стандартное сравнение упорядочивает числа по возрастанию."},{"id":"16","title":"Лямбды","minutes":25,"theory":["Лямбда — локальный функциональный объект. [] задаёт захват переменных, параметры указываются в ().","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"std::vector<int> v{1,4,2}; std::sort(v.begin(),v.end(), [](int a,int b){return a>b;});","task":"Отсортируй числа по убыванию и посчитай положительные через count_if.","criteria":["Лямбда-компаратор","count_if","проверка вывода"],"question":"Что обозначает [] в лямбде?","options":["Размер массива","Список захвата","Тип int"],"correct":1,"explanation":"Квадратные скобки определяют захват внешних переменных."},{"id":"17","title":"Файлы и потоки","minutes":25,"theory":["ofstream записывает файл, ifstream читает; оба автоматически закрывают файл при выходе из области видимости. Проверяй состояние потока.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"{ std::ofstream out(\"tasks.txt\"); out << \"Learn C++\\n\"; }\nstd::ifstream in(\"tasks.txt\"); std::string line; while(std::getline(in,line)) std::cout << line;","task":"Запиши три задачи в файл и прочитай их. Проверь успешность открытия.","criteria":["ofstream","ifstream","проверка ошибок"],"question":"Какой поток предназначен для чтения файла?","options":["ifstream","cout","ofstream"],"correct":0,"explanation":"ifstream читает данные из файла."},{"id":"18","title":"Ошибки и тесты","minutes":25,"theory":["Проверяй ввод до вычисления, используй assert для проверок в отладочной сборке. assert может отключаться через NDEBUG, поэтому это не проверка пользовательского ввода.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"#include <cassert>\n// В main: assert(square(3)==9); assert(square(0)==0);","task":"Напиши функцию min2 и тесты с равными, отрицательными и разными числами.","criteria":["Три проверки","ожидаемые значения","функция работает"],"question":"Что означает провал assert?","options":["Проверенное условие ложно","Изменился цвет экрана","Программа всегда исправна"],"correct":0,"explanation":"assert сигнализирует о нарушенном условии в активной сборке."},{"id":"19","title":"Проект: модель и сервис","minutes":35,"theory":["Храни задачи в vector<Task>. Отдельные функции добавляют, показывают и меняют статус; перед доступом по индексу проверяй размер.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"struct Task { std::string title; bool done=false; };\nvoid add(std::vector<Task>& tasks,const std::string& title){tasks.push_back({title,false});}","task":"Создай модель и функции add/list/done. Проверь недопустимый индекс.","criteria":["Модель","три функции","проверка индекса"],"question":"Зачем проверять индекс перед доступом?","options":["Чтобы увеличить файл","Чтобы избежать выхода за границы","Чтобы поменять тип"],"correct":1,"explanation":"Некорректный индекс может привести к неопределённому поведению."},{"id":"20","title":"Проект: меню и сохранение","minutes":35,"theory":["Цикл меню принимает команды, вызывает функции и завершает работу по exit. Сохранение в файл должно восстанавливать и название, и статус.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"int choice=0; while(std::cin>>choice && choice!=0){switch(choice){case 1: std::cout<<\"List\\n\"; break; default: std::cout<<\"Unknown\\n\";}}","task":"Добавь меню, сохранение и загрузку задач с флагом выполнения. Проверь неверную команду.","criteria":["Меню","сохранены оба поля","обработка ошибок"],"question":"Как выйти из показанного цикла?","options":["Ввести 1","Ввести любое число","Ввести 0"],"correct":2,"explanation":"Условие choice!=0 становится ложным при 0."},{"id":"21","title":"Финал: C++ Task Manager","minutes":35,"theory":["Собери консольное приложение с моделью, файлами и проверками. Используй стандарт C++17, не усложняй проект ручным управлением памятью. Курс даёт основы.","Пример — фрагмент C++17: подключи нужные заголовки стандартной библиотеки, инструкции помести в main, функции и классы — вне main. Проверяй код локальным компилятором."],"example":"// main.cpp, task.hpp, task.cpp\n// g++ -std=c++17 -Wall -Wextra main.cpp task.cpp -o app","task":"Подготовь рабочий менеджер задач, README и три сценария проверки: добавление, завершение, восстановление.","criteria":["Сборка без ошибок","данные восстанавливаются","README и сценарии"],"question":"Что важнее при финальной проверке?","options":["Количество комментариев","Длина названия","Работающий проект и тесты"],"correct":1,"explanation":"Работающие сценарии дают проверяемый результат."}]}]}],"ai":[{"day":1,"title":"Что такое AI на самом деле","description":"Разбираемся без магии: что умеют современные AI-инструменты, чего не умеют и где они уже рядом с вами.","duration":25,"category":"Основы","keywords":["что такое","ai","ии","нейросет","искусственный интеллект","основы"],"sections":[{"heading":"AI — это не робот из кино","body":["Когда говорят «AI», чаще всего имеют в виду языковые модели вроде ChatGPT, Claude, Gemini или GigaChat. Это программы, обученные на огромном объёме текстов и умеющие продолжать текст так, чтобы он выглядел осмысленно и полезно.","У модели нет сознания, желаний и доступа к вашей жизни. Она не «знает» ответ, а вычисляет наиболее вероятное продолжение с учётом вашего запроса. Поэтому результат сильно зависит от того, как вы спросили."]},{"heading":"Где AI уже помогает","body":["Учёба: объяснить тему простыми словами, составить план повторения, сделать тест для самопроверки. Работа: черновик письма, структура презентации, разбор таблицы. Жизнь: план поездки, бюджет, сравнение вариантов.","Главный принцип курса: AI — это быстрый ассистент для черновиков и идей, а финальное решение и проверка остаются за вами."]},{"heading":"Три режима использования","body":["Объяснитель — помогает понять. Генератор — создаёт черновики и варианты. Критик — находит слабые места в вашем тексте или плане. Опытные пользователи переключаются между этими режимами осознанно."]}],"examples":[{"label":"Объяснитель","bad":"Что такое инфляция","good":"Объясни инфляцию студенту первого курса на примере цен на кофе за 3 года. До 120 слов.","why":"Указаны аудитория, пример и объём — ответ сразу становится полезнее."},{"label":"Критик","good":"Вот мой план подготовки к экзамену. Найди 3 слабых места и предложи, как их исправить.","why":"Вы просите не сделать за вас, а улучшить вашу работу."}],"practice":{"title":"Моя AI-карта","task":"Опишите 3 ситуации из вашей учёбы, работы или жизни, где AI мог бы помочь уже на этой неделе. Для каждой укажите режим (объяснитель, генератор или критик) и что вы будете проверять сами.","steps":["Вспомните задачи, которые отнимают у вас время","Выберите три реальные ситуации","Для каждой назовите режим и что проверите сами"],"minLength":120},"checklist":["Я описал(а) три конкретные ситуации, а не общие слова","Для каждой указан режим использования","Я понимаю, что проверка результата остаётся за мной"],"mentorTip":"Начните с самой скучной задачи недели — на ней эффект AI заметнее всего.","extra":{"sections":[{"heading":"AI, машинное обучение и генеративные модели","body":["Искусственный интеллект — общее название методов, с помощью которых программы решают задачи распознавания, прогнозирования и создания материалов. Это не человек в компьютере и не гарантия правильного ответа.","Машинное обучение — часть AI: вместо ручного описания всех правил систему обучают на примерах. Спам-фильтр учится отличать нежелательные письма, а рекомендательная система — предсказывать интерес к материалам. Генеративный AI создаёт новые тексты, изображения или звук на основе закономерностей обучения.","Обычный калькулятор выполняет заданное арифметическое правило. Классификатор оценивает, к какому классу относится объект. Генеративная модель составляет новый ответ. Выбирайте инструмент по задаче: для точной суммы надёжнее калькулятор, для черновика объяснения полезна языковая модель."]},{"heading":"Где помощь заканчивается и начинается ответственность","body":["Разделите задачу на вход, действие и проверяемый результат. Например: вход — обезличенный конспект; действие — выделить главные мысли; результат — пять тезисов, каждый подтверждается исходным текстом.","AI может пропустить условие, придумать факт или воспроизвести предвзятость данных. Ответственность за отправленное письмо, учебную работу или решение остаётся у человека. Медицинские, юридические и финансовые решения требуют компетентной проверки.","Мини-упражнение: выберите одну задачу на неделю и заранее запишите критерий успеха. Не «AI помог», а «получился план из пяти пунктов без выдуманных сроков»."]}],"examples":[{"label":"Выбор инструмента","bad":"Пусть чат точно посчитает итог 500 строк расходов без проверки.","good":"Посчитаю итог формулой в таблице, а AI попрошу объяснить структуру бюджета на обезличенных данных.","why":"Детерминированный инструмент считает, модель помогает сформулировать и объяснить; результат можно проверить."}],"quiz":[{"id":"ai-purpose","question":"Какой пример относится к генеративному AI?","options":["Калькулятор умножает 7 на 8","Модель создаёт черновик письма по описанию","Таймер отсчитывает 60 секунд"],"correct":1,"explanation":"Генеративный AI создаёт новый материал; вычисление по фиксированному правилу и таймер сами по себе не являются генерацией."},{"id":"ai-responsibility","question":"Кто отвечает за достоверность письма, подготовленного с AI?","options":["Человек, который проверяет и отправляет письмо","Модель, потому что пишет уверенно","Никто, это автоматически верный текст"],"correct":0,"explanation":"Перед отправкой человек проверяет факты, адресата, тон и условия. Уверенная формулировка не доказывает истинность."},{"id":"ai-safe-input","question":"Как безопаснее составить учебный план с AI?","options":["Передать пароли и полный паспорт","Попросить гарантировать сдачу экзамена","Указать темы, срок и доступное время без лишних личных данных"],"correct":2,"explanation":"Для плана нужны учебные ограничения, а не секреты. Модель не может гарантировать результат экзамена."}]}},{"day":2,"title":"Контекст и ограничения","description":"Добавляем цель, исходные данные и проверяемые условия, чтобы AI не угадывал вашу ситуацию.","duration":20,"category":"Промптинг","keywords":["контекст","ограничен","данные","формат","рзкф"],"sections":[{"heading":"Что сообщить перед запросом","body":["Контекст — это сведения, без которых задача неоднозначна: для кого нужен ответ, что уже известно, какие материалы доступны и какой результат вы хотите получить. Не вставляйте пароли, чужие контакты и лишние личные данные.","Используйте формулу «роль → задача → контекст → формат». Например, роль — учебный помощник; задача — план повторения; контекст — новичок, три темы, три дня; формат — таблица. Роль необязательна, но цель и данные должны быть понятны."]},{"heading":"Как задать ограничения","body":["Укажите измеримые условия: 25 минут в день, только перечисленные темы, три строки таблицы. «Сделай идеально» нельзя проверить. Если данных мало, попросите сначала задать вопросы, а не придумывать недостающее.","Материал для самостоятельной работы: экзамен через три дня, темы — спрос, предложение и равновесие; уровень — начинающий; доступно 25 минут в день. План должен включать одно упражнение на каждый день и не добавлять новые темы. Внешний AI для выполнения не нужен."]}],"examples":[{"label":"Запрос до и после доработки","bad":"Подготовь меня к экзамену.","good":"Ты учебный помощник. Составь план повторения микроэкономики для новичка на 3 дня, по 25 минут ежедневно. Темы: спрос, предложение, равновесие. Ответ — таблица из 3 строк: день, тема, упражнение, минуты. Не добавляй другие темы. Если данных недостаточно, сначала уточни их.","why":"Есть цель, уровень, темы, время и формат. Теперь результат можно сверить с конкретными условиями."}],"practice":{"title":"Соберите понятный запрос","task":"Возьмите слабый запрос «Подготовь меня к экзамену» и доработайте его по исходным данным выше либо под свою учебную задачу. В ответе напишите: «До», «После», затем объясните, какие сведения и ограничения добавили и как проверите результат. Запускать внешнюю модель не нужно.","steps":["Запишите исходный запрос","Добавьте контекст, условия и формат","Объясните проверку результата"],"minLength":150},"checklist":["В ответе есть запрос до и после доработки","Указаны цель, уровень ученика и конкретные темы","Есть минимум два измеримых ограничения и формат ответа","Я объяснил(а), как проверить соблюдение условий, без лишних личных данных"],"mentorTip":"Проверьте запрос как инструкцию для незнакомого человека: понятно ли ему, что делать и чего не делать?","extra":{"sections":[],"examples":[],"quiz":[{"id":"context-details","question":"Какой запрос содержит полезный контекст и ограничения?","options":["Сделай всё идеально","Ты гений, помоги","Я новичок; повторяю спрос и предложение 3 дня по 25 минут; нужен план таблицей"],"correct":2,"explanation":"Указаны уровень, темы, срок, время и формат — это проверяемые условия."},{"id":"context-missing","question":"Что попросить, если для плана не хватает данных?","options":["Сначала задать уточняющие вопросы","Придумать мой график","Игнорировать ограничения"],"correct":0,"explanation":"Уточняющие вопросы полезнее выдуманных обстоятельств. Лишние личные данные не нужны."},{"id":"context-quality","question":"Как проверить соблюдение ограничения «25 минут в день»?","options":["По уверенности тона","Сложить длительность шагов каждого дня и сравнить с 25 минутами","По числу красивых слов"],"correct":1,"explanation":"Измеримое условие проверяют по результату: суммарное время не должно превышать доступное."}]}},{"day":3,"title":"Как уточнить слабый ответ","description":"Находим конкретную проблему и пишем уточнение вместо просьбы «сделай лучше».","duration":20,"category":"Промптинг","keywords":["уточн","слабый","доработ","обратная связь","итерац","промпт"],"sections":[{"heading":"Первый ответ — черновик","body":["Если ответ слабый, назовите проблему: пропущено условие, слишком общий совет, неверный уровень или неподходящий формат. Скажите, что нужно сохранить и что изменить. Так уточнение направляет правку, а не заставляет модель заново угадывать цель.","Формула уточнения: «В ответе не выполнено X. Сохрани Y. Исправь Z. Результат представь в формате F». Меняйте один аспект за раз и сравнивайте с теми же критериями."]},{"heading":"Учебный ответ для разбора","body":["Исходная задача: повторить спрос и предложение за два дня по 20 минут. Демонстрационный слабый ответ: «Изучи всю экономику, прочитай учебник и реши много задач». Он не учитывает темы, срок и доступное время. Это заранее подготовленный пример, не ответ настоящей модели.","Для проверки новой версии спросите себя: только ли две темы остались, укладывается ли каждый день в 20 минут и есть ли конкретное упражнение? Даже после уточнения результат нужно прочитать."]}],"examples":[{"label":"Уточнение до и после доработки","bad":"Нет, сделай лучше.","good":"В твоём плане слишком общий совет «изучи всю экономику». Сохрани цель — повторить спрос и предложение. Сделай таблицу на 2 дня, по 20 минут в день, с одним конкретным упражнением ежедневно. Не добавляй новые темы; укажи время каждого шага.","why":"Названы недостаток, сохраняемая цель и проверяемый результат. Не нужно угадывать значение слова «лучше»."}],"practice":{"title":"Исправьте слабый ответ","task":"Разберите демонстрационный ответ выше. Напишите слабое уточнение и его улучшенную версию. Назовите минимум две проблемы исходного ответа, укажите, что сохранить, и вручную составьте ожидаемый план на два дня. Подпишите его «Мой вариант без запуска AI» и объясните, как проверите исправление.","steps":["Найдите две проблемы","Напишите конкретное уточнение","Составьте и проверьте свой вариант"],"minLength":150},"checklist":["Я назвал(а) не менее двух конкретных проблем","Есть слабое и улучшенное уточнение с указанием, что сохранить","Мой вариант содержит два дня по 20 минут и конкретные упражнения","Я сравнил(а) результат с условиями и честно отметил(а), что AI не запускался"],"mentorTip":"Замените «не нравится» на наблюдение: какое условие нарушено и какой результат нужен вместо него?","extra":{"sections":[],"examples":[],"quiz":[{"id":"refine-specific","question":"Какое уточнение поможет исправить слишком общий план?","options":["Сделай лучше","Ты всё понял неправильно","Сохрани две темы; добавь упражнения на 2 дня по 20 минут, без новых тем"],"correct":2,"explanation":"Конкретная обратная связь указывает, что сохранить, что изменить и как проверить новую версию."},{"id":"refine-compare","question":"Как сравнивать версии ответа?","options":["Выбирать самую длинную","Проверять обе по одним и тем же условиям задачи","Каждый раз менять цель"],"correct":1,"explanation":"Постоянные критерии помогают увидеть, исправлена ли исходная проблема."},{"id":"refine-review","question":"Нужно ли читать ответ после уточнения?","options":["Да, повторно сверить факты и условия","Нет, уточнения гарантируют точность","Только если текст короткий"],"correct":0,"explanation":"Уточнение не гарантирует правильности; результат требует повторной проверки."}]}},{"day":4,"title":"Как проверять факты и источники","description":"Отделяем уверенный тон от доказательств: открываем источник, сверяем содержание и дату.","duration":25,"category":"Ответственность","keywords":["факт","источник","ссылк","провер","цитат","достовер"],"sections":[{"heading":"Ссылка ещё не доказательство","body":["Языковая модель может придумать цифру, цитату или название статьи. Проверяйте: существует ли источник, подтверждает ли он именно это утверждение и актуален ли он для вашей задачи. При важных выводах ищите независимое подтверждение.","Если источник недоступен или в нём нет утверждения, пишите «не подтверждено», а не «точно ложь». Не выдавайте поисковый заголовок или повтор ответа чат-бота за проверку."]},{"heading":"Учебные материалы для проверки без интернета","body":["Все следующие материалы вымышлены для упражнения. Карточка А: «Правила учебной библиотеки “Пример”, редакция от 01.09.2026: студент может взять до 5 книг на 14 дней». Карточка Б: «Заметка студенческого клуба от 10.09.2024: раньше книги выдавали на 7 дней». Это не реальные источники и не ссылки.","Демонстрационный ответ: «В библиотеке “Пример” разрешено взять 10 книг на 14 дней; за просрочку взимается 500 рублей». По карточке А количество книг противоречит тексту, срок подтверждён в рамках карточки, а штраф не подтверждён ни одним из материалов. Учебная сверка не доказывает правила какой-либо настоящей библиотеки."]}],"examples":[{"label":"Запрос до и после доработки","bad":"Дай точные правила библиотеки и ссылки, даже если не уверен.","good":"Проверь три утверждения из ответа по карточкам А и Б. Таблица: утверждение, подтверждающий фрагмент, дата материала, вердикт. Различай «подтверждено», «противоречит материалу» и «нет данных». Не придумывай ссылки. Для настоящих правил я отдельно проверю официальный сайт библиотеки.","why":"Разделены данные упражнения и реальные факты. Есть проверяемые фрагменты, даты и явное поведение при нехватке сведений."}],"practice":{"title":"Проверьте три утверждения","task":"Запишите запрос до и после доработки для проверки ответа о библиотеке. Затем самостоятельно проверьте количество книг, срок выдачи и штраф по карточкам выше. Для каждого укажите вердикт, основание и дату материала либо «нет данных». Объясните, где проверили бы настоящие правила. Не выдавайте вымышленные карточки за реальные источники.","steps":["Улучшите запрос проверки","Проверьте три утверждения","Укажите границы учебной проверки"],"minLength":180},"checklist":["Есть запрос до и после с запретом выдумывать источники","Для каждого из трёх утверждений есть отдельный вердикт и основание","Указаны дата и фрагмент карточки либо отсутствие данных","Я отделил(а) вымышленные материалы от реальных источников и назвал(а) способ независимой проверки"],"mentorTip":"«Нет данных» — корректный результат проверки. Не заменяйте пробел убедительной догадкой.","extra":{"sections":[],"examples":[],"quiz":[{"id":"facts-evidence","question":"Что доказывает наличие ссылки в AI-ответе?","options":["Само по себе ничего: надо открыть источник, сверить содержание и дату","Что все факты точны","Что это первоисточник"],"correct":0,"explanation":"Ссылки бывают вымышленными, устаревшими или не подтверждающими утверждение."},{"id":"facts-missing","question":"Карточки не содержат сведений о штрафе. Какой вердикт корректен?","options":["Штраф точно составляет 500 рублей","Штрафов точно не существует","Нет данных о штрафе в предоставленных материалах"],"correct":2,"explanation":"Отсутствие сведений не подтверждает ни размер штрафа, ни полное отсутствие штрафов."},{"id":"facts-scope","question":"Можно ли по вымышленной карточке подтвердить правила реальной библиотеки?","options":["Да, если текст убедителен","Нет, нужно проверить актуальный официальный источник настоящей библиотеки","Да, если модель повторит ответ"],"correct":1,"explanation":"Учебные материалы подтверждают выводы только в рамках упражнения, а не реальные правила."}]}},{"day":5,"title":"Как применять AI в учёбе","description":"Делаем план повторения и самопроверку, сохраняя самостоятельность и учебную честность.","duration":25,"category":"Практика","keywords":["учёб","учеб","повтор","карточк","конспект","экзамен","самопровер"],"sections":[{"heading":"Помощник, а не замена вашему мышлению","body":["AI полезен для объяснения непонятного места, карточек по конспекту и вопросов для самопроверки. Сначала попробуйте ответить сами, затем сравните с материалом и разберите ошибку. Перечитывание готового решения не показывает, можете ли вы решить задачу самостоятельно.","Уточняйте правила преподавателя об использовании AI. Не сдавайте чужой или сгенерированный ответ как собственную самостоятельную работу. Для проверки фактов обращайтесь к учебному материалу, а не к уверенности модели."]},{"heading":"Тренировка без внешнего сервиса","body":["Мини-конспект: «Спрос — количество товара, которое покупатели готовы приобрести при заданных условиях. Предложение — количество, которое продавцы готовы продать. При прочих равных рост цены обычно уменьшает величину спроса и увеличивает величину предложения».","Запланируйте 20 минут: 5 на объяснение терминов, 10 на ответы своими словами, 5 на разбор ошибок. Два вопроса: чем спрос отличается от предложения; как при прочих равных рост цены влияет на величину спроса? Сначала ответьте без подсказки, затем сверьте с конспектом. Эта самостоятельная тренировка не требует подключения AI."]}],"examples":[{"label":"Запрос до и после доработки","bad":"Сделай домашку по экономике за меня.","good":"Помоги мне самостоятельно повторить спрос и предложение по приведённому конспекту. У меня 20 минут, я новичок. Задавай по одному вопросу и жди моего ответа, не показывай решение заранее. После ответа объясняй ошибку по конспекту и предлагай короткое упражнение. Не добавляй новые факты. Конспект: [мой текст].","why":"Ученик отвечает сам, источник ограничен, а ошибки превращаются в план повторения, а не в готовую работу для сдачи."}],"practice":{"title":"Спроектируйте учебную сессию","task":"Напишите запрос до и после доработки для своей учебной задачи либо для мини-конспекта выше. Составьте план на 20 минут. Самостоятельно ответьте на два вопроса из конспекта (или своей темы), сверьте ответы с материалом и запишите одну ошибку либо пробел и следующий шаг повторения. Пометьте работу как самостоятельную сессию без AI.","steps":["Запрос и план на 20 минут","Два самостоятельных ответа","Сверка и следующий шаг"],"minLength":180},"checklist":["Есть запрос до и после с темой, источником и режимом вопросов по одному","План укладывается в 20 минут и включает самопроверку","Я дал(а) два собственных ответа и сверил(а) их с материалом","Назван конкретный пробел и шаг повторения; соблюдена учебная честность"],"mentorTip":"Просите не готовое решение, а вопрос, подсказку и разбор вашей собственной попытки.","extra":{"sections":[],"examples":[],"quiz":[{"id":"study-independent","question":"Как AI полезнее использовать для самопроверки?","options":["Сразу читать готовые ответы","Получать вопросы по одному, отвечать самому, затем разбирать ошибки","Копировать решение без чтения"],"correct":1,"explanation":"Самостоятельное воспроизведение и разбор ошибок показывают, что вы понимаете, а что нужно повторить."},{"id":"study-honesty","question":"Как использовать AI при подготовке работы для преподавателя?","options":["Всегда выдавать текст модели за собственный","Считать любые правила необязательными","Уточнить правила курса и честно обозначить использование AI, если требуется"],"correct":2,"explanation":"Допустимость помощи зависит от правил учебной работы; AI не отменяет ответственность ученика."},{"id":"study-next","question":"Что делать после ошибки на учебном вопросе?","options":["Свериться с конспектом, записать пробел и назначить упражнение для повторения","Считать тему навсегда непонятной","Попросить модель похвалить ответ"],"correct":0,"explanation":"Конкретный пробел и следующий шаг превращают ошибку в полезный план обучения."}]}},{"day":6,"title":"Поиск информации и фактчекинг","description":"Как исследовать тему с AI и не попасться на выдуманные факты. Метод трёх проверок.","duration":35,"category":"Практика","keywords":["поиск","факт","провер","источник","исследован","ссылк","достовер"],"sections":[{"heading":"AI как навигатор по теме","body":["Используйте AI, чтобы быстро получить карту темы: ключевые понятия, спорные вопросы, термины для поиска. А факты — подтверждайте в первоисточниках."]},{"heading":"Метод трёх проверок","body":["1. Источник: есть ли реальная ссылка и открывается ли она. 2. Подтверждение: находится ли тот же факт в независимом надёжном источнике. 3. Свежесть: актуальна ли информация на сегодня.","Если факт не прошёл хотя бы одну проверку — не используйте его в работе."]},{"heading":"Красные флаги","body":["Слишком круглые или слишком точные цифры без источника. Цитаты известных людей, которые нигде не находятся. Ссылки на статьи с правдоподобными, но несуществующими названиями."]}],"examples":[{"label":"Карта темы","good":"Я исследую тему «удалённая работа и продуктивность». Дай 7 ключевых понятий, 3 спорных вопроса и поисковые запросы на русском и английском.","why":"Вы получаете направление поиска, а не готовые «факты»."}],"practice":{"title":"Фактчек трёх утверждений","task":"Попросите AI дать 3 факта по теме, которая вам интересна. Проверьте каждый методом трёх проверок и опишите результат: подтверждён, не подтверждён или устарел — и где вы это проверили.","steps":["Получите 3 факта","Проверьте источник, подтверждение и свежесть","Запишите вердикт по каждому"],"minLength":160},"checklist":["Для каждого факта указан вердикт","Я назвал(а) реальные места проверки","Я сделал(а) вывод о надёжности ответа"],"mentorTip":"Просите у AI поисковые запросы, а не ссылки — так надёжнее.","extra":{"sections":[],"examples":[],"quiz":[{"id":"fact-primary","question":"AI назвал исследование. Что сделать перед использованием вывода?","options":["Поверить уверенной формулировке","Найти первоисточник и проверить, подтверждает ли он вывод","Убрать ссылку, чтобы не отвлекала"],"correct":1,"explanation":"Нужно проверить существование источника, соответствие утверждению и актуальность. Название статьи в ответе AI ещё ничего не подтверждает."},{"id":"fact-missing","question":"Подтверждение факта не удалось найти. Как записать результат?","options":["Факт доказан","Факт точно ложный","Не подтверждён; указать, что именно проверили"],"correct":2,"explanation":"Отсутствие найденного подтверждения не доказывает ложность. Честно фиксируйте неопределённость и ход проверки."}]}},{"day":7,"title":"Генерация изображений","description":"Как описывать картинку словами: объект, стиль, композиция, свет. Плюс честные правила использования.","duration":30,"category":"Креатив","keywords":["изображ","картин","рисун","midjourney","dall","kandinsky","визуал","дизайн","обложк"],"sections":[{"heading":"Анатомия визуального промпта","body":["Объект: что изображено. Стиль: фотография, акварель, плоская иллюстрация. Композиция: крупный план, вид сверху. Свет и цвет: мягкий утренний свет, пастельная палитра. Назначение: обложка презентации, иконка."]},{"heading":"Итерации и варианты","body":["Генерируйте несколько вариантов и меняйте по одному параметру за раз. Так вы поймёте, какое слово на что влияет.","Текст на изображениях генераторы часто искажают — надписи лучше добавлять в редакторе."]},{"heading":"Этика и права","body":["Не создавайте изображения реальных людей без согласия и не выдавайте сгенерированное за фотодокумент. Проверяйте условия использования сервиса для коммерческих задач."]}],"examples":[{"label":"Обложка","bad":"Картинка про учёбу","good":"Плоская иллюстрация: студентка за столом с ноутбуком и стопкой книг, вид сбоку, тёплая палитра персикового и бирюзового, много свободного места справа для заголовка, без текста.","why":"Указаны стиль, композиция, цвет и место под заголовок."}],"practice":{"title":"Обложка для проекта","task":"Придумайте обложку для презентации или поста. Напишите три версии визуального промпта, меняя по одному параметру. Опишите, какая версия лучше подходит и почему (если есть доступ к генератору — опишите полученные результаты).","steps":["Определите назначение","Три версии промпта","Выбор и аргументация"],"minLength":150},"checklist":["Каждый промпт содержит объект, стиль и композицию","Версии отличаются одним параметром","Я учёл(учла) этические ограничения"],"mentorTip":"Меняйте один параметр за раз — это быстрее, чем переписывать всё.","extra":{"sections":[],"examples":[],"quiz":[{"id":"image-iterate","question":"Как понять, почему визуальный промпт стал лучше?","options":["Менять один параметр за итерацию","Каждый раз менять все условия","Увеличивать длину без цели"],"correct":0,"explanation":"Изменение одного параметра помогает связать результат с конкретной правкой: композицией, светом или стилем."},{"id":"image-rights","question":"Что важно проверить перед использованием сгенерированного изображения?","options":["Только разрешение файла","Права использования, согласие на чужую внешность и соответствие задаче","Количество слов в промпте"],"correct":1,"explanation":"Генерация не отменяет требований к правам, приватности и ответственному использованию чужого образа."}]}},{"day":8,"title":"AI для учёбы и продуктивности","description":"Конспекты, карточки, планы и активное повторение. AI как личный тренер по учёбе, а не шпаргалка.","duration":30,"category":"Практика","keywords":["учёб","учеб","экзамен","конспект","карточк","продуктив","план","повтор","тест","сессия"],"sections":[{"heading":"Активное повторение","body":["Перечитывание даёт иллюзию знания. Работает самопроверка: попросите AI задавать вам вопросы по теме по одному, не показывая ответов, и разбирать ваши ошибки."]},{"heading":"Объяснение по уровням","body":["«Объясни как пятикласснику, затем как студенту, затем как специалисту». Так вы видите, на каком уровне начинается непонимание."]},{"heading":"Планирование без перегруза","body":["Дайте AI свой реальный календарь и попросите разбить большую задачу на шаги по 25–40 минут. Просите оставлять буфер: идеальные планы ломаются первыми."]}],"examples":[{"label":"Тренажёр","good":"Ты экзаменатор по теме «Клеточное дыхание». Задавай мне по одному вопросу, жди ответа, затем коротко оценивай и объясняй ошибку. Начни с простого.","why":"Интерактивная самопроверка вместо пассивного чтения."}],"practice":{"title":"Учебная сессия с AI","task":"Проведите 15-минутную сессию самопроверки по своей теме в режиме экзаменатора. Опишите тему, сколько вопросов было, где ошиблись и какой план повторения составили на основе ошибок.","steps":["Выберите тему","Пройдите сессию вопросов","Запишите ошибки и план"],"minLength":150},"checklist":["Я отвечал(а) сам(а), не подглядывая","Я записал(а) конкретные ошибки","У меня есть план повторения"],"mentorTip":"Просите вопросы по одному — так сессия становится настоящей тренировкой.","extra":{"sections":[],"examples":[],"quiz":[{"id":"study-recall","question":"Какой способ лучше помогает проверить понимание?","options":["Перечитать готовый ответ несколько раз","Скопировать конспект без изменений","Ответить самостоятельно и разобрать ошибки"],"correct":2,"explanation":"Активное воспроизведение выявляет пробелы. AI может задавать вопросы, но собственное объяснение и сверка остаются за учеником."},{"id":"study-plan","question":"Что включить в план повторения?","options":["Ошибки, конкретные темы и посильное время","Только список всех тем сразу","Обещание модели, что экзамен будет сдан"],"correct":0,"explanation":"Реалистичный план строят вокруг обнаруженных пробелов и доступного времени, а не гарантии внешнего результата."}]}},{"day":9,"title":"Таблицы и данные","description":"Формулы, анализ, выводы. Как AI помогает с Excel и Google Таблицами, если вы не аналитик.","duration":35,"category":"Данные","keywords":["таблиц","excel","данн","формул","sheets","анализ","бюджет","график"],"sections":[{"heading":"Формулы на человеческом языке","body":["Опишите задачу словами: «В столбце B суммы расходов, в C категории. Нужна сумма по категории «еда» за март». AI предложит формулу и объяснит её по частям.","Всегда проверяйте формулу на 2–3 строках, где ответ можно посчитать вручную."]},{"heading":"Структура данных","body":["Одна строка — одна запись, один столбец — один признак, без объединённых ячеек. Попросите AI предложить структуру таблицы под вашу задачу ещё до того, как вы начнёте её заполнять."]},{"heading":"От цифр к выводам","body":["Покажите AI обезличенную сводку и спросите: «Какие 3 закономерности ты видишь и как их проверить?». Выводы модели — гипотезы, а не доказательства."]}],"examples":[{"label":"Формула","good":"Google Таблицы. A — дата, B — сумма, C — категория. Напиши формулу суммы по категории «транспорт» за текущий месяц и объясни каждую часть.","why":"Указаны программа, структура и просьба объяснить."}],"practice":{"title":"Мини-бюджет","task":"Спроектируйте с AI таблицу для учёта бюджета, учебного времени или тренировок. Опишите столбцы, 2 формулы, которые получили, и как вы проверили их корректность.","steps":["Выберите задачу","Получите структуру и формулы","Проверьте формулы вручную"],"minLength":150},"checklist":["Структура соответствует правилу «строка — запись»","Я описал(а) минимум две формулы","Я проверил(а) формулы вручную"],"mentorTip":"Тестируйте формулы на маленьком примере с известным ответом.","extra":{"sections":[],"examples":[],"quiz":[{"id":"data-formula","question":"AI предложил формулу таблицы. Как её проверить?","options":["Считать верной, если синтаксис сложный","Сравнить с ручным расчётом на маленьком наборе и проверить границы","Оценить по длине ответа"],"correct":1,"explanation":"Контрольный пример с известным ответом, пустыми значениями и границами помогает найти ошибки формулы."},{"id":"data-private","question":"Какие данные безопаснее использовать в учебном бюджете?","options":["Пароли банковского кабинета","Паспорт и номера карт","Вымышленные или обезличенные операции"],"correct":2,"explanation":"Для проектирования таблицы реальные секреты и идентифицирующие сведения не нужны."}]}},{"day":10,"title":"Основы кода с AI","description":"Не нужно быть программистом, чтобы автоматизировать мелочи. Читаем, запускаем и понимаем простой код.","duration":40,"category":"Данные","keywords":["код","программ","python","скрипт","javascript","ошибк","баг","функци"],"sections":[{"heading":"Код как рецепт","body":["Программа — последовательность понятных шагов. AI может написать короткий скрипт на Python, например переименовать файлы или посчитать слова в тексте. Ваша задача — понять, что он делает, прежде чем запускать."]},{"heading":"Просите объяснение построчно","body":["«Объясни этот код построчно, как новичку». «Какие данные он может испортить?». «Как протестировать его на копии файлов?» — три вопроса, которые стоит задавать всегда."]},{"heading":"Ошибки — это нормально","body":["Скопируйте текст ошибки целиком и покажите AI вместе с кодом. Опишите, что ожидали и что получили. Чаще всего проблема решается за 1–2 итерации.","Попробовать Python можно в онлайн-средах вроде Google Colab или Replit без установки."]}],"examples":[{"label":"Безопасный старт","good":"Напиши Python-скрипт, который считает, сколько раз каждое слово встречается в тексте. Добавь комментарии на русском к каждой строке и пример запуска.","why":"Маленькая задача, комментарии и пример — легко понять и проверить."}],"practice":{"title":"Первый скрипт","task":"Попросите AI написать маленький скрипт для полезной вам задачи. Опишите задачу, вставьте код или его ключевую часть, объясните своими словами, что делает каждая часть, и что произошло при запуске.","steps":["Сформулируйте маленькую задачу","Получите код с комментариями","Объясните своими словами и запустите"],"minLength":160},"checklist":["Я могу объяснить, что делает код","Я запускал(а) или тестировал(а) код на безопасных данных","Я описал(а) результат или ошибку"],"mentorTip":"Никогда не запускайте код, который не можете объяснить хотя бы в общих чертах.","extra":{"sections":[],"examples":[],"quiz":[{"id":"code-review","question":"Что сделать перед запуском кода от AI?","options":["Разобрать код, проверить действия и подготовить безопасные тестовые данные","Запустить от администратора без чтения","Передать все пароли для настройки"],"correct":0,"explanation":"Неизвестный код может изменять файлы или отправлять данные. Сначала поймите действия и проверьте риски, затем тестируйте на безопасном наборе."},{"id":"code-claim","question":"Можно ли считать код работающим без запуска?","options":["Да, если модель уверена","Нет; можно лишь описать ожидаемое поведение и отдельно отметить отсутствие проверки","Да, если есть комментарии"],"correct":1,"explanation":"Объяснение и чтение не заменяют выполнение тестов. Не выдавайте ожидаемый результат за реально наблюдавшийся."}]}},{"day":11,"title":"Автоматизация рутины","description":"Шаблоны промптов, цепочки задач и no-code сервисы. Экономим часы каждую неделю.","duration":30,"category":"Продуктивность","keywords":["автоматиз","рутин","шаблон","zapier","make","no-code","повторя","workflow","цепочк"],"sections":[{"heading":"Найдите повторяющееся","body":["Автоматизировать стоит то, что вы делаете чаще раза в неделю и по одному сценарию: еженедельный отчёт, ответы на типовые письма, конспект лекций по одной структуре."]},{"heading":"Библиотека промптов","body":["Самая простая автоматизация — сохранённые шаблоны с переменными: «Сделай конспект лекции [ТЕМА] по структуре: 5 главных идей, 3 термина, 2 вопроса для самопроверки». Храните их в заметках."]},{"heading":"Цепочки и сервисы","body":["Сложные задачи разбивайте на шаги: собрать → сократить → оформить. No-code сервисы вроде Make или Zapier связывают приложения, но начните с ручной цепочки — так вы поймёте процесс."]}],"examples":[{"label":"Шаблон","good":"Шаблон еженедельного отчёта: «Вот мои заметки за неделю: [ЗАМЕТКИ]. Сделай отчёт: что сделано, что в процессе, блокеры, план. Не больше 120 слов».","why":"Один раз написали — используете каждую неделю."}],"practice":{"title":"Мой первый шаблон","task":"Найдите повторяющуюся задачу и создайте для неё шаблон промпта с переменными в квадратных скобках. Опишите задачу, сколько времени она занимала и сколько, по-вашему, сэкономит шаблон. Протестируйте его один раз.","steps":["Найдите повторяющуюся задачу","Напишите шаблон с переменными","Протестируйте и оцените экономию"],"minLength":150},"checklist":["Задача действительно повторяется регулярно","В шаблоне есть переменные","Я протестировал(а) шаблон на реальных данных"],"mentorTip":"Начинайте с ручной цепочки, автоматизируйте только проверенное.","extra":{"sections":[],"examples":[],"quiz":[{"id":"automation-template","question":"Что делает шаблон промпта пригодным для повторения?","options":["Секретные данные внутри","Отсутствие проверки","Явные переменные, условия и критерий результата"],"correct":2,"explanation":"Переменные отделяют постоянную инструкцию от меняющихся данных, а критерий помогает каждый раз проверить ответ."},{"id":"automation-time","question":"Как честно оценивать экономию времени?","options":["Отделять прогноз от измерения и учитывать время проверки","Всегда обещать экономию 90%","Не считать исправления"],"correct":0,"explanation":"Автоматизация требует проверки и исправлений. Измеренная экономия и предположение должны быть обозначены отдельно."}]}},{"day":12,"title":"Приватность и этика","description":"Что нельзя вставлять в чат, как честно использовать AI в учёбе и работе и где проходят границы.","duration":25,"category":"Ответственность","keywords":["приватн","этик","безопасн","данн","персональн","плагиат","честн","конфиденц","пароль"],"sections":[{"heading":"Правило светофора","body":["Красный — никогда: пароли, номера карт и паспортов, чужие персональные данные, коммерческая тайна. Жёлтый — после обезличивания: рабочие документы, переписка. Зелёный — свободно: общие вопросы, ваши собственные черновики без личных деталей."]},{"heading":"Честное использование","body":["Узнайте правила вуза или работодателя. Если AI помог существенно — скажите об этом. Не выдавайте сгенерированный текст за полностью свой там, где это запрещено."]},{"heading":"Предвзятость и ответственность","body":["Модели могут воспроизводить стереотипы из обучающих данных. Если решение касается людей — найма, оценки, доступа — финальное слово и ответственность за человеком."]}],"examples":[{"label":"Обезличивание","bad":"Вот договор с ООО «...» и паспортные данные клиента, найди риски","good":"Вот обезличенный фрагмент договора, где стороны заменены на «Сторона А» и «Сторона Б». Какие пункты стоит проверить юристу?","why":"Задача решена без утечки данных."}],"practice":{"title":"Мои правила AI","task":"Составьте личный свод из 5–7 правил использования AI: что вы никогда не вставляете, как обезличиваете данные, когда сообщаете об использовании AI. Приведите пример одной ситуации, где правило бы сработало.","steps":["Используйте светофор","Сформулируйте 5–7 правил","Приведите пример"],"minLength":150},"checklist":["Есть правила для «красных» данных","Есть правило об открытости использования AI","Приведён конкретный пример"],"mentorTip":"Если сомневаетесь, можно ли вставить данные, — значит, нельзя без обезличивания.","extra":{"sections":[],"examples":[],"quiz":[{"id":"privacy-secrets","question":"Что нельзя вставлять в обычный AI-чат?","options":["Обезличенный учебный пример","Пароли, ключи и конфиденциальные данные без разрешённого процесса","Общую структуру плана"],"correct":1,"explanation":"Секреты и конфиденциальные сведения требуют отдельного безопасного процесса. Для учебной задачи достаточно обезличенного контекста."},{"id":"ethics-responsibility","question":"Кто проверяет предвзятость и уместность результата?","options":["Никто, если ответ звучит спокойно","Только модель","Человек, принимающий и использующий результат"],"correct":2,"explanation":"Ответственность не передаётся модели. Перед применением человек проверяет содержание и возможный вред."}]}},{"day":13,"title":"Ваш собственный AI-проект","description":"Выбираем реальную задачу, планируем и собираем рабочий процесс из всего, что изучили.","duration":40,"category":"Проект","keywords":["проект","идея","собственн","свой","планиров","задач"],"sections":[{"heading":"Выбор задачи","body":["Хороший проект: реальная польза для вас или знакомых, решается за 2–4 часа, результат можно показать. Примеры: учебный ассистент по сложному предмету, система учёта расходов, контент-план для блога, подготовка к собеседованию."]},{"heading":"План проекта","body":["Проблема: что не так сейчас. Результат: что будет на выходе. Инструменты: какие AI-сервисы и навыки курса. Шаги: 4–6 конкретных действий. Проверка: как поймёте, что получилось."]},{"heading":"Минимальная версия","body":["Сделайте сначала самую простую рабочую версию, а потом улучшайте. Готовый простой проект ценнее идеального, который не закончен."]}],"examples":[{"label":"Пример плана","good":"Проблема: трачу 2 часа на подготовку к семинару. Результат: шаблон, который за 30 минут делает конспект, вопросы и тезисы. Инструменты: чат-ассистент, шаблон промпта, таблица. Проверка: время подготовки и оценка на семинаре.","why":"Чёткая проблема и измеримый результат."}],"practice":{"title":"План проекта","task":"Опишите свой AI-проект по структуре: проблема, результат, инструменты, 4–6 шагов, критерий успеха. Выполните хотя бы первый шаг и опишите, что получилось.","steps":["Проблема и результат","Инструменты и шаги","Критерий успеха и первый шаг"],"minLength":200},"checklist":["Проблема реальная и конкретная","Шаги можно выполнить за 2–4 часа","Есть измеримый критерий успеха","Первый шаг выполнен"],"mentorTip":"Сузьте проект до задачи, которую можно закончить за один вечер.","extra":{"sections":[],"examples":[],"quiz":[{"id":"project-scope","question":"Как выбрать объём первого AI-проекта?","options":["Одна конкретная задача с проверяемым результатом","Все задачи компании сразу","Как можно больше сервисов без цели"],"correct":0,"explanation":"Небольшой проверяемый объём позволяет закончить проект и понять реальную пользу."},{"id":"project-criterion","question":"Какой критерий успеха проверяем?","options":["Получилось впечатляюще","План из пяти шагов учитывает срок и не содержит выдуманных фактов","Модель написала, что всё идеально"],"correct":1,"explanation":"Явные условия позволяют независимо сравнить результат с задачей, а не полагаться на впечатление или самооценку модели."}]}},{"day":14,"title":"Финальный проект и следующий шаг","description":"Завершаем проект, делаем рефлексию и составляем личный план развития после курса.","duration":45,"category":"Проект","keywords":["финал","итог","рефлекс","дальше","следующ","после курса","развит","портфолио"],"sections":[{"heading":"Доведите до результата","body":["Завершите проект из дня 13. Соберите результат так, чтобы его можно было показать: документ, таблица, шаблон, презентация. Добавьте короткое описание: что делает и как пользоваться."]},{"heading":"Рефлексия","body":["Что получилось лучше всего? Где AI сэкономил больше всего времени? Где пришлось исправлять за ним? Какие навыки курса оказались самыми полезными?"]},{"heading":"План на 30 дней","body":["Выберите 2–3 навыка для углубления и одну регулярную привычку: например, каждую пятницу улучшать один шаблон. Маленькие регулярные шаги делают вас уверенным пользователем."]}],"examples":[{"label":"Портфолио","good":"Опиши мой проект для портфолио в 4 предложениях: проблема, решение, использованные инструменты, результат в цифрах. Тон — уверенный, без преувеличений.","why":"Проект превращается в аргумент для резюме."}],"practice":{"title":"Финальный отчёт","task":"Опишите итог проекта: что получилось, как им пользоваться, какой результат (время, качество, польза). Добавьте рефлексию по курсу и план развития на 30 дней с 2–3 навыками и одной привычкой.","steps":["Итог проекта","Рефлексия","План на 30 дней"],"minLength":220},"checklist":["Проект доведён до показываемого результата","Рефлексия содержит конкретные наблюдения","План на 30 дней содержит навыки и привычку"],"mentorTip":"Запишите результат в цифрах — это лучший аргумент для себя и для работодателя.","extra":{"sections":[],"examples":[],"quiz":[{"id":"final-evidence","question":"Что включить в итоговый отчёт?","options":["Только красивое название","Только весь чат без пояснений","Задачу, свой результат, способ проверки и ограничения"],"correct":2,"explanation":"Итог должен показывать собственную работу, подтверждение результата и границы применения."},{"id":"final-next","question":"Какой следующий шаг после курса полезнее?","options":["Выбрать небольшую реальную задачу и запланировать проверяемую практику","Считать, что больше учиться не нужно","Автоматически доверять любому AI-ответу"],"correct":0,"explanation":"Навык укрепляется осмысленной практикой и проверкой, а завершение курса не снимает ответственности за новые задачи."}]}}]};

